-- Step 19: attendance, the modern way — QR scanning (kiosk at the gate / teacher's phone), biometric & RFID devices,
--          staff self check-in by location, manual class-wise as before; staff attendance; low-attendance report;
--          punches log; QR codes for ID cards.
-- Safe to run again.
-- ═══════════════════════════════════════════════════════════════════════════

-- ───────────── Settings ─────────────
create table if not exists public.attendance_settings (
  school_id      uuid primary key references public.schools(id) on delete cascade,
  school_start   time not null default '08:00',
  late_after     time not null default '08:15',
  geofence_m     int  not null default 150 check (geofence_m between 30 and 2000),
  updated_at     timestamptz not null default now()
);
alter table public.attendance_settings enable row level security;
drop policy if exists "read" on public.attendance_settings;
create policy "read" on public.attendance_settings for select to authenticated using (public.has_module_perm(school_id, 'attendance'));
drop policy if exists "write" on public.attendance_settings;
create policy "write" on public.attendance_settings for all to authenticated
  using (public.has_perm_school(school_id, 'attendance.students.edit')) with check (public.has_perm_school(school_id, 'attendance.students.edit'));

-- ───────────── Columns ─────────────
alter table public.attendance add column if not exists source text not null default 'manual';
alter table public.attendance drop constraint if exists attendance_source_check;
alter table public.attendance add constraint attendance_source_check check (source in ('manual', 'qr', 'biometric', 'rfid', 'import', 'geo'));
alter table public.attendance add column if not exists in_time time;
alter table public.attendance add column if not exists out_time time;
alter table public.attendance add column if not exists note text;

alter table public.students add column if not exists att_code text;
update public.students set att_code = encode(gen_random_bytes(6), 'hex') where att_code is null;
alter table public.students alter column att_code set default encode(gen_random_bytes(6), 'hex');
create unique index if not exists students_att_code on public.students (att_code);

alter table public.staff add column if not exists att_code text;
update public.staff set att_code = encode(gen_random_bytes(6), 'hex') where att_code is null;
alter table public.staff alter column att_code set default encode(gen_random_bytes(6), 'hex');
create unique index if not exists staff_att_code on public.staff (att_code);

-- ───────────── Devices and punches ─────────────
create table if not exists public.attendance_devices (
  id           uuid primary key default gen_random_uuid(),
  school_id    uuid not null references public.schools(id) on delete cascade,
  name         text not null check (length(btrim(name)) > 0),
  kind         text not null default 'qr_kiosk' check (kind in ('qr_kiosk', 'biometric', 'rfid')),
  location     text,
  token        text not null unique default encode(gen_random_bytes(12), 'hex'),
  active       boolean not null default true,
  last_seen_at timestamptz,
  created_at   timestamptz not null default now()
);
create table if not exists public.attendance_punches (
  id          bigint generated always as identity primary key,
  school_id   uuid not null references public.schools(id) on delete cascade,
  device_id   uuid references public.attendance_devices(id) on delete set null,
  subject     text not null check (subject in ('student', 'staff')),
  student_id  uuid references public.students(id) on delete cascade,
  staff_id    uuid references public.staff(id) on delete cascade,
  punched_at  timestamptz not null default now(),
  source      text not null,
  direction   text,
  result      text not null,           -- in / out / already / unknown / inactive / error
  raw         text
);
create index if not exists attendance_punches_idx on public.attendance_punches (school_id, punched_at desc);

create table if not exists public.staff_attendance (
  id         uuid primary key default gen_random_uuid(),
  school_id  uuid not null references public.schools(id) on delete cascade,
  staff_id   uuid not null references public.staff(id) on delete cascade,
  date       date not null,
  status     text not null check (status in ('P', 'A', 'L', 'H', 'LV', 'OD')),     -- present, absent, late, half day, leave, on duty
  in_time    time,
  out_time   time,
  source     text not null default 'manual' check (source in ('manual', 'qr', 'biometric', 'rfid', 'import', 'geo')),
  note       text,
  marked_by  text,
  marked_at  timestamptz not null default now(),
  unique (staff_id, date)
);
create index if not exists staff_attendance_date_idx on public.staff_attendance (school_id, date);

alter table public.attendance_devices enable row level security;
alter table public.attendance_punches enable row level security;
alter table public.staff_attendance enable row level security;
drop policy if exists "read" on public.attendance_devices;
create policy "read" on public.attendance_devices for select to authenticated using (public.has_perm_school(school_id, 'attendance.students.edit'));
drop policy if exists "read" on public.attendance_punches;
create policy "read" on public.attendance_punches for select to authenticated
  using (public.has_perm_school(school_id, 'attendance.students.edit') or public.has_perm_school(school_id, 'attendance.staff.view'));
drop policy if exists "read" on public.staff_attendance;
create policy "read" on public.staff_attendance for select to authenticated
  using (public.has_perm_school(school_id, 'attendance.staff.view') or exists (select 1 from public.staff s where s.id = staff_id and s.user_id = auth.uid()));
-- devices and punches are written by the functions below; staff attendance by the functions and the policies here
drop policy if exists "create" on public.staff_attendance;
create policy "create" on public.staff_attendance for insert to authenticated with check (public.has_perm_school(school_id, 'attendance.staff.create'));
drop policy if exists "edit" on public.staff_attendance;
create policy "edit" on public.staff_attendance for update to authenticated using (public.has_perm_school(school_id, 'attendance.staff.edit') or public.has_perm_school(school_id, 'attendance.staff.create'));

-- ───────────── Punch core ─────────────
create or replace function public._punch_core(sid uuid, p_kind text, p_subject uuid, p_at timestamptz, p_dir text, p_source text, p_device uuid, p_by text, p_raw text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare cfg record; d date := (p_at at time zone 'Asia/Kolkata')::date; tm time := date_trunc('second', (p_at at time zone 'Asia/Kolkata'))::time;
        late time; st text; ex record; res text := 'in'; nm text; cls text; stu record; stf record; sid2 uuid;
begin
  select * into cfg from public.attendance_settings where school_id = sid;
  late := coalesce(cfg.late_after, time '08:15');
  if d > public.today_ist() then raise exception 'That time is in the future.'; end if;
  st := case when tm > late then 'L' else 'P' end;

  if p_kind = 'student' then
    select s.id, s.status, s.class_id, s.section_id, btrim(concat_ws(' ', s.first_name, s.middle_name, s.last_name)) as nm, c.name as cname, sec.name as sname
      into stu from public.students s left join public.classes c on c.id = s.class_id left join public.sections sec on sec.id = s.section_id where s.id = p_subject and s.school_id = sid;
    if stu.id is null then raise exception 'Student not found.'; end if;
    nm := stu.nm; cls := concat_ws('-', stu.cname, stu.sname);
    if stu.status <> 'active' then
      insert into public.attendance_punches (school_id, device_id, subject, student_id, punched_at, source, direction, result, raw) values (sid, p_device, 'student', stu.id, p_at, p_source, p_dir, 'inactive', p_raw);
      return jsonb_build_object('ok', false, 'result', 'inactive', 'name', nm, 'class', cls, 'message', 'This student is not currently on roll.');
    end if;
    select * into ex from public.attendance where student_id = stu.id and date = d;
    if ex.id is null then
      insert into public.attendance (school_id, student_id, class_id, section_id, date, status, marked_by, source, in_time) values (sid, stu.id, stu.class_id, stu.section_id, d, st, p_by, p_source, tm);
    elsif ex.status in ('A', 'LV') then
      update public.attendance set status = st, source = p_source, in_time = tm, out_time = null, marked_by = p_by, marked_at = now(), note = null where id = ex.id;
    elsif ex.in_time is null then
      update public.attendance set in_time = tm, source = case when ex.source = 'manual' then ex.source else p_source end where id = ex.id;
    elsif tm >= ex.in_time + interval '10 minutes' and (ex.out_time is null or tm > ex.out_time) then
      update public.attendance set out_time = tm where id = ex.id; res := 'out';
    else
      res := 'already';
    end if;
    insert into public.attendance_punches (school_id, device_id, subject, student_id, punched_at, source, direction, result, raw) values (sid, p_device, 'student', stu.id, p_at, p_source, p_dir, res, p_raw);
    return jsonb_build_object('ok', true, 'result', res, 'kind', 'student', 'name', nm, 'class', cls, 'status', case when ex.id is null or ex.status in ('A','LV') then st else ex.status end, 'time', to_char(tm, 'HH24:MI'), 'late', st = 'L' and res = 'in');
  end if;

  select s.id, s.name, s.status, s.designation into stf from public.staff s where s.id = p_subject and s.school_id = sid;
  if stf.id is null then raise exception 'Staff member not found.'; end if;
  if stf.status <> 'active' then
    insert into public.attendance_punches (school_id, device_id, subject, staff_id, punched_at, source, direction, result, raw) values (sid, p_device, 'staff', stf.id, p_at, p_source, p_dir, 'inactive', p_raw);
    return jsonb_build_object('ok', false, 'result', 'inactive', 'name', stf.name, 'message', 'This staff member is not working here.');
  end if;
  select * into ex from public.staff_attendance where staff_id = stf.id and date = d;
  if ex.id is null then
    insert into public.staff_attendance (school_id, staff_id, date, status, in_time, source, marked_by) values (sid, stf.id, d, st, tm, p_source, p_by);
  elsif ex.status in ('A', 'LV') then
    update public.staff_attendance set status = st, in_time = tm, out_time = null, source = p_source, marked_by = p_by, marked_at = now() where id = ex.id;
  elsif ex.in_time is null then
    update public.staff_attendance set in_time = tm where id = ex.id;
  elsif tm >= ex.in_time + interval '10 minutes' and (ex.out_time is null or tm > ex.out_time) then
    update public.staff_attendance set out_time = tm where id = ex.id; res := 'out';
  else
    res := 'already';
  end if;
  insert into public.attendance_punches (school_id, device_id, subject, staff_id, punched_at, source, direction, result, raw) values (sid, p_device, 'staff', stf.id, p_at, p_source, p_dir, res, p_raw);
  return jsonb_build_object('ok', true, 'result', res, 'kind', 'staff', 'name', stf.name, 'class', stf.designation, 'status', case when ex.id is null or ex.status in ('A','LV') then st else ex.status end, 'time', to_char(tm, 'HH24:MI'), 'late', st = 'L' and res = 'in');
end $$;
revoke execute on function public._punch_core(uuid, text, uuid, timestamptz, text, text, uuid, text, text) from public, anon, authenticated;

-- the code printed on an ID card (QR) or typed in by a biometric device: att_code, else admission no., else employee code
create or replace function public._find_subject(sid uuid, p_code text) returns table (kind text, id uuid)
language sql stable security definer set search_path = public as $$
  select x.kind, x.id from (
    select 'student'::text, s.id, 1 as pri from public.students s where s.school_id = sid and s.att_code = lower(btrim(p_code))
    union all select 'staff', t.id, 2 from public.staff t where t.school_id = sid and t.att_code = lower(btrim(p_code))
    union all select 'student', s.id, 3 from public.students s where s.school_id = sid and lower(s.admission_no) = lower(btrim(p_code))
    union all select 'staff', t.id, 4 from public.staff t where t.school_id = sid and t.emp_code is not null and lower(t.emp_code) = lower(btrim(p_code))
  ) x(kind, id, pri) order by pri limit 1;
$$;
revoke execute on function public._find_subject(uuid, text) from public, anon, authenticated;

-- ───────────── Device side (the app server, with the device's private token) ─────────────
create or replace function public.device_scan(p_token text, p_code text, p_at timestamptz default null, p_dir text default null, p_raw text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare dv public.attendance_devices; f record; r jsonb; src text;
begin
  if not public.is_service() then raise exception 'not allowed'; end if;
  if p_token is null or p_token !~ '^[0-9a-f]{24}$' then raise exception 'This device link is not valid.'; end if;
  select * into dv from public.attendance_devices where token = p_token and active;
  if dv.id is null then raise exception 'This device link is not valid or the device is switched off.'; end if;
  if p_code is null or length(btrim(p_code)) < 1 or length(p_code) > 60 then raise exception 'Nothing was scanned.'; end if;
  update public.attendance_devices set last_seen_at = now() where id = dv.id;
  select * into f from public._find_subject(dv.school_id, p_code);
  if f.id is null then
    insert into public.attendance_punches (school_id, device_id, subject, punched_at, source, direction, result, raw)
    values (dv.school_id, dv.id, 'student', coalesce(p_at, now()), case dv.kind when 'qr_kiosk' then 'qr' else dv.kind end, p_dir, 'unknown', left(p_code, 60));
    return jsonb_build_object('ok', false, 'result', 'unknown', 'message', 'This code is not on any student or staff card.');
  end if;
  src := case dv.kind when 'qr_kiosk' then 'qr' when 'biometric' then 'biometric' else 'rfid' end;
  r := public._punch_core(dv.school_id, f.kind, f.id, coalesce(p_at, now()), p_dir, src, dv.id, dv.name, left(p_code, 60));
  return r;
end $$;
revoke execute on function public.device_scan(text, text, timestamptz, text, text) from public, anon, authenticated;
grant execute on function public.device_scan(text, text, timestamptz, text, text) to service_role;

-- "who am I" for a kiosk page
create or replace function public.device_info(p_token text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare dv public.attendance_devices;
begin
  if not public.is_service() then raise exception 'not allowed'; end if;
  select * into dv from public.attendance_devices where token = p_token and active;
  if dv.id is null then raise exception 'This device link is not valid or the device is switched off.'; end if;
  update public.attendance_devices set last_seen_at = now() where id = dv.id;
  return jsonb_build_object('name', dv.name, 'kind', dv.kind, 'school', (select name from public.schools where id = dv.school_id),
    'today', (select count(*) from public.attendance_punches p where p.device_id = dv.id and p.punched_at >= (public.today_ist())::timestamp at time zone 'Asia/Kolkata' and p.result in ('in', 'out')));
end $$;
revoke execute on function public.device_info(text) from public, anon, authenticated;
grant execute on function public.device_info(text) to service_role;

-- ───────────── Staff side ─────────────
-- A teacher scans a student's QR with the ERP (permission follows the class assignment).
create or replace function public.scan_attendance(sid uuid, p_code text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare f record; sec uuid;
begin
  if auth.uid() is null then raise exception 'not allowed'; end if;
  select * into f from public._find_subject(sid, p_code);
  if f.id is null then return jsonb_build_object('ok', false, 'result', 'unknown', 'message', 'This code is not on any student or staff card.'); end if;
  if f.kind = 'student' then
    select section_id into sec from public.students where id = f.id;
    if not coalesce(public.can_section(sid, 'attendance.students.create', sec), false) then raise exception 'not allowed — this student is not in your class.'; end if;
  elsif not public.has_perm_school(sid, 'attendance.staff.create') then
    raise exception 'not allowed';
  end if;
  return public._punch_core(sid, f.kind, f.id, now(), null, 'qr', null, coalesce(auth.jwt() ->> 'email', ''), left(p_code, 60));
end $$;

-- A staff member checks in from their own phone, only near the school.
create or replace function public.staff_check_in(sid uuid, p_lat numeric, p_lng numeric) returns jsonb
language plpgsql security definer set search_path = public as $$
declare stf record; sc record; cfg record; dist numeric;
begin
  if auth.uid() is null then raise exception 'not allowed'; end if;
  select s.id, s.name into stf from public.staff s where s.school_id = sid and s.user_id = auth.uid() and s.status = 'active';
  if stf.id is null then raise exception 'Your login is not linked to a staff record.'; end if;
  select lat, lng into sc from public.schools where id = sid;
  if sc.lat is null or sc.lng is null then raise exception 'The school location is not set yet (Transport → Live bus map → School location).'; end if;
  select * into cfg from public.attendance_settings where school_id = sid;
  dist := public.geo_km(sc.lat, sc.lng, p_lat, p_lng) * 1000;
  if dist > coalesce(cfg.geofence_m, 150) then
    return jsonb_build_object('ok', false, 'result', 'far', 'message', 'You are about ' || round(dist) || ' m from the school. Check in when you reach.', 'distance_m', round(dist));
  end if;
  return public._punch_core(sid, 'staff', stf.id, now(), null, 'geo', null, stf.name, null) || jsonb_build_object('distance_m', round(dist));
end $$;

-- CSV import of punches (a biometric machine's export): code, date-time
create or replace function public.import_punch(sid uuid, p_code text, p_at timestamptz) returns jsonb
language plpgsql security definer set search_path = public as $$
declare f record;
begin
  if not (public.has_perm_school(sid, 'attendance.students.edit') or public.has_perm_school(sid, 'attendance.staff.create')) then raise exception 'not allowed'; end if;
  select * into f from public._find_subject(sid, p_code);
  if f.id is null then return jsonb_build_object('ok', false, 'result', 'unknown'); end if;
  return public._punch_core(sid, f.kind, f.id, p_at, null, 'import', null, coalesce(auth.jwt() ->> 'email', ''), left(p_code, 60));
end $$;

-- device management
create or replace function public.rotate_device_token(did uuid) returns text
language plpgsql security definer set search_path = public as $$
declare d record; t text;
begin
  select * into d from public.attendance_devices where id = did;
  if d.id is null or not public.has_perm_school(d.school_id, 'attendance.students.edit') then raise exception 'not allowed'; end if;
  t := encode(gen_random_bytes(12), 'hex');
  update public.attendance_devices set token = t where id = did;
  return t;
end $$;

create or replace function public.add_device(sid uuid, p_name text, p_kind text, p_location text) returns uuid
language plpgsql security definer set search_path = public as $$
declare i uuid;
begin
  if not public.has_perm_school(sid, 'attendance.students.edit') then raise exception 'not allowed'; end if;
  if coalesce(btrim(p_name), '') = '' then raise exception 'Give the device a name.'; end if;
  if p_kind not in ('qr_kiosk', 'biometric', 'rfid') then raise exception 'Unknown device type.'; end if;
  insert into public.attendance_devices (school_id, name, kind, location) values (sid, btrim(p_name), p_kind, nullif(btrim(coalesce(p_location, '')), '')) returning id into i;
  return i;
end $$;

-- ───────────── Reports ─────────────
create or replace function public.attendance_day(sid uuid, on_day date)
returns table (class_id uuid, section_id uuid, class_name text, section_name text, strength bigint, present bigint, late bigint, half bigint, absent bigint, leave bigint, not_marked bigint, scanned bigint)
language sql stable set search_path = public as $$
  select c.id, sec.id, c.name, sec.name, count(s.id),
         count(a.id) filter (where a.status in ('P', 'L', 'H')), count(a.id) filter (where a.status = 'L'), count(a.id) filter (where a.status = 'H'),
         count(a.id) filter (where a.status = 'A'), count(a.id) filter (where a.status = 'LV'),
         count(s.id) filter (where a.id is null), count(a.id) filter (where a.source <> 'manual')
    from public.students s
    join public.classes c on c.id = s.class_id
    join public.sections sec on sec.id = s.section_id
    left join public.attendance a on a.student_id = s.id and a.date = on_day
   where s.school_id = sid and s.status = 'active'
   group by c.id, c.name, c.sort, sec.id, sec.name
   order by c.sort, sec.name;
$$;

create or replace function public.attendance_low(sid uuid, d1 date, d2 date, thr numeric default 75, cls uuid default null, sec uuid default null, p_q text default null,
                                                 p_limit int default 25, p_offset int default 0)
returns table (student_id uuid, admission_no text, student_name text, class_name text, section_name text, guardian_phone text, father_name text,
               marked bigint, present bigint, absent bigint, pct numeric, total bigint)
language sql stable set search_path = public as $$
  with agg as (
    select s.id, s.admission_no, btrim(concat_ws(' ', s.first_name, s.middle_name, s.last_name)) as nm, c.name as cname, c.sort as csort, sec2.name as secname, s.guardian_phone, s.father_name,
           count(a.id) as marked, count(a.id) filter (where a.status in ('P', 'L', 'H')) as pres, count(a.id) filter (where a.status = 'A') as abs
      from public.students s
      left join public.classes c on c.id = s.class_id left join public.sections sec2 on sec2.id = s.section_id
      left join public.attendance a on a.student_id = s.id and a.date between d1 and d2
     where s.school_id = sid and s.status = 'active' and (cls is null or s.class_id = cls) and (sec is null or s.section_id = sec)
       and (nullif(btrim(coalesce(p_q, '')), '') is null or concat_ws(' ', s.first_name, s.middle_name, s.last_name) ilike public.like_escape(btrim(p_q)) or s.admission_no ilike public.like_escape(btrim(p_q)))
     group by s.id, c.name, c.sort, sec2.name
  )
  select g.id, g.admission_no, g.nm, g.cname, g.secname, g.guardian_phone, g.father_name, g.marked, g.pres, g.abs,
         round(100.0 * g.pres / nullif(g.marked, 0), 1), count(*) over ()
    from agg g
   where g.marked > 0 and 100.0 * g.pres / g.marked < thr
   order by 100.0 * g.pres / g.marked asc, g.csort nulls last, g.nm
   limit least(greatest(coalesce(p_limit, 25), 1), 200) offset greatest(coalesce(p_offset, 0), 0);
$$;

create or replace function public.staff_attendance_day(sid uuid, on_day date)
returns table (staff_id uuid, name text, emp_code text, designation text, department text, status text, in_time time, out_time time, source text, note text, leave_kind text)
language sql stable security definer set search_path = public as $$
  select s.id, s.name, s.emp_code, s.designation, s.department, a.status, a.in_time, a.out_time, a.source, a.note,
         (select l.kind from public.staff_leaves l where l.staff_id = s.id and l.status = 'approved' and on_day between l.from_date and l.to_date limit 1)
    from public.staff s left join public.staff_attendance a on a.staff_id = s.id and a.date = on_day
   where s.school_id = sid and s.status = 'active' and public.has_perm_school(sid, 'attendance.staff.view')
   order by s.name;
$$;

-- one month per staff member; suggested unpaid days for payroll
create or replace function public.staff_attendance_month(sid uuid, p_month date)
returns table (staff_id uuid, name text, emp_code text, present numeric, late bigint, half bigint, absent bigint, leave_days numeric, on_duty bigint, marked bigint, working_days int, suggested_lop numeric)
language plpgsql stable security definer set search_path = public as $$
declare m1 date := date_trunc('month', p_month)::date; m2 date := (date_trunc('month', p_month) + interval '1 month - 1 day')::date; wd int; days int[];
begin
  if not public.has_perm_school(sid, 'attendance.staff.view') then return; end if;
  select coalesce(array(select jsonb_array_elements_text(prefs -> 'working_days')::int), array[1,2,3,4,5,6]) into days from public.schools where id = sid;
  if days is null or cardinality(days) = 0 then days := array[1,2,3,4,5,6]; end if;
  select count(*) into wd from generate_series(m1, m2, interval '1 day') g where extract(isodow from g)::int = any(days);
  return query
    select s.id, s.name, s.emp_code,
           coalesce(sum(case when a.status in ('P', 'L', 'OD') then 1 when a.status = 'H' then 0.5 else 0 end), 0),
           count(*) filter (where a.status = 'L'), count(*) filter (where a.status = 'H'), count(*) filter (where a.status = 'A'),
           coalesce((select sum(l.days) from public.staff_leaves l where l.staff_id = s.id and l.status = 'approved' and l.kind <> 'LWP' and l.from_date <= m2 and l.to_date >= m1), 0)::numeric,
           count(*) filter (where a.status = 'OD'), count(a.id), wd,
           greatest(wd - coalesce(sum(case when a.status in ('P', 'L', 'OD') then 1 when a.status = 'H' then 0.5 else 0 end), 0)
                       - coalesce((select sum(l.days) from public.staff_leaves l where l.staff_id = s.id and l.status = 'approved' and l.kind <> 'LWP' and l.from_date <= m2 and l.to_date >= m1), 0), 0)::numeric
      from public.staff s left join public.staff_attendance a on a.staff_id = s.id and a.date between m1 and m2
     where s.school_id = sid and s.status = 'active'
     group by s.id, s.name, s.emp_code
     order by s.name;
end $$;

-- ───────────── QR on ID cards and documents ─────────────
do $$
begin
  if exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'document_data')
     and not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'document_data_base') then
    alter function public.document_data(uuid, uuid, uuid, text, date, date, jsonb) rename to document_data_base;
  end if;
end $$;
create or replace function public.document_data(sid uuid, stu uuid, stf uuid, doc_no text, on_day date, valid_until date, p_extra jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare d jsonb;
begin
  d := public.document_data_base(sid, stu, stf, doc_no, on_day, valid_until, p_extra);
  if stu is not null then d := jsonb_set(d, '{student,att_code}', to_jsonb((select att_code from public.students where id = stu)), true); end if;
  if stf is not null then d := jsonb_set(d, '{staff,att_code}', to_jsonb((select att_code from public.staff where id = stf)), true); end if;
  return d;
end $$;
revoke execute on function public.document_data(uuid, uuid, uuid, text, date, date, jsonb) from public, anon, authenticated;
revoke execute on function public.document_data_base(uuid, uuid, uuid, text, date, date, jsonb) from public, anon, authenticated;

create or replace function public.render_document(body text, data jsonb) returns text
language plpgsql immutable as $$
declare out text := regexp_replace(coalesce(body, ''), '\{\{\s*([a-zA-Z0-9_.]+)\s*\}\}', '{{\1}}', 'g'); k text; v text;
begin
  for k in select distinct t.m[1] from regexp_matches(out, '\{\{([a-zA-Z0-9_.]+)\}\}', 'g') as t(m) loop
    v := data #>> string_to_array(k, '.');
    if k = 'student.photo' then
      out := replace(out, '{{' || k || '}}', '<img class="doc-photo" data-photo="1" src="" alt="Photograph" style="width:100%;height:100%;object-fit:cover">');
    elsif k = 'school.logo' then
      out := replace(out, '{{' || k || '}}', case when v ~* '^https://' then '<img class="doc-logo" src="' || public.html_escape(v) || '" alt="Logo" style="width:100%;height:100%;object-fit:contain">' else '' end);
    elsif k in ('student.qr', 'staff.qr') then
      v := data #>> string_to_array(case when k = 'student.qr' then 'student.att_code' else 'staff.att_code' end, '.');
      out := replace(out, '{{' || k || '}}', case when v ~ '^[0-9a-f]{12}$' then '<img class="doc-qr" data-qr="' || v || '" src="" alt="QR" style="width:100%;height:100%;object-fit:contain">' else '' end);
    elsif k ~ '^fee\.[a-z_]+_html$' then
      out := replace(out, '{{' || k || '}}', coalesce(v, ''));
    else
      out := replace(out, '{{' || k || '}}', public.html_escape(v));
    end if;
  end loop;
  return out;
end $$;

-- ───────────── Audit ─────────────
do $$
declare t text;
begin
  foreach t in array array['attendance_settings', 'attendance_devices'] loop
    execute format('drop trigger if exists audit_%1$s on public.%1$I', t);
    execute format('create trigger audit_%1$s after insert or update or delete on public.%1$I for each row execute function public.audit_row()', t);
  end loop;
end $$;

-- ═══════════════════════════════════════════════════════════════════════════
-- Step 20: Accounts — income & expense vouchers, cash / bank books, one day book.
--   Fee receipts, paid refunds and approved payroll flow into the day book by themselves (no double entry).
--   Manual vouchers (donation, electricity bill, repairs …) go through an optional approval threshold.
-- Safe to run again.
-- ═══════════════════════════════════════════════════════════════════════════

-- ───────────── Heads, books, settings ─────────────
create table if not exists public.account_heads (
  id         uuid primary key default gen_random_uuid(),
  school_id  uuid not null references public.schools(id) on delete cascade,
  name       text not null check (length(btrim(name)) between 1 and 60),
  kind       text not null check (kind in ('income', 'expense')),
  active
       boolean not null default true,
  created_at timestamptz not null default now()
);
create unique index if not exists account_heads_name on public.account_heads (school_id, kind, lower(name));

create table if not exists public.account_books (
  id              uuid primary key default gen_random_uuid(),
  school_id       uuid not null references public.schools(id) on delete cascade,
  name            text not null check (length(btrim(name)) between 1 and 60),
  kind            text not null check (kind in ('cash', 'bank')),
  opening_balance numeric(14,2) not null default 0,
  opening_date    date not null default (now() at time zone 'Asia/Kolkata')::date,
  account_no      text,
  active          boolean not null default true,
  created_at      timestamptz not null default now()
);
create unique index if not exists account_books_name on public.account_books (school_id, lower(name));

create table if not exists public.account_settings (
  school_id       uuid primary key references public.schools(id) on delete cascade,
  approval_above  numeric(14,2) not null default 0 check (approval_above >= 0),   -- 0 = no approval needed
  next_no         int not null default 1
);

-- ───────────── Vouchers ─────────────
create table if not exists public.vouchers (
  id              uuid primary key default gen_random_uuid(),
  school_id       uuid not null references public.schools(id) on delete cascade,
  no              text not null,
  date            date not null,
  kind            text not null check (kind in ('receipt', 'payment', 'transfer')),
  head_id         uuid references public.account_heads(id) on delete restrict,
  book_id         uuid not null references public.account_books(id) on delete restrict,
  to_book_id      uuid references public.account_books(id) on delete restrict,
  amount          numeric(14,2) not null check (amount > 0),
  party           text,
  mode            text,
  ref_no          text,
  narration       text,
  status          text not null default 'posted' check (status in ('posted', 'pending', 'rejected', 'cancelled')),
  created_by      uuid default auth.uid() references auth.users(id) on delete set null,
  created_by_name text,
  decided_by_name text,
  decided_at      timestamptz,
  decision_note   text,
  created_at      timestamptz not null default now(),
  unique (school_id, no),
  check ((kind = 'transfer' and to_book_id is not null and to_book_id <> book_id and head_id is null) or (kind <> 'transfer' and head_id is not null and to_book_id is null))
);
create index if not exists vouchers_day_idx on public.vouchers (school_id, date, status);

alter table public.account_heads enable row level security;
alter table public.account_books enable row level security;
alter table public.account_settings enable row level security;
alter table public.vouchers enable row level security;

drop policy if exists "read" on public.account_heads;
create policy "read" on public.account_heads for select to authenticated using (public.has_module_perm(school_id, 'accounts'));
drop policy if exists "write" on public.account_heads;
create policy "write" on public.account_heads for all to authenticated
  using (public.has_perm_school(school_id, 'accounts.vouchers.edit')) with check (public.has_perm_school(school_id, 'accounts.vouchers.edit'));
drop policy if exists "read" on public.account_books;
create policy "read" on public.account_books for select to authenticated using (public.has_module_perm(school_id, 'accounts'));
drop policy if exists "write" on public.account_books;
create policy "write" on public.account_books for all to authenticated
  using (public.has_perm_school(school_id, 'accounts.vouchers.edit')) with check (public.has_perm_school(school_id, 'accounts.vouchers.edit'));
drop policy if exists "read" on public.account_settings;
create policy "read" on public.account_settings for select to authenticated using (public.has_module_perm(school_id, 'accounts'));
drop policy if exists "write" on public.account_settings;
create policy "write" on public.account_settings for all to authenticated
  using (public.has_perm_school(school_id, 'accounts.vouchers.edit')) with check (public.has_perm_school(school_id, 'accounts.vouchers.edit'));
drop policy if exists "read" on public.vouchers;
create policy "read" on public.vouchers for select to authenticated
  using (public.has_perm_school(school_id, 'accounts.vouchers.view') or public.has_perm_school(school_id, 'accounts.books.view'));
-- vouchers are written only by the functions below

-- ───────────── Defaults ─────────────
create or replace function public._account_defaults(sid uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  insert into public.account_settings (school_id) values (sid) on conflict do nothing;
  if not exists (select 1 from public.account_books where school_id = sid) then
    insert into public.account_books (school_id, name, kind) values (sid, 'Cash in hand', 'cash');
  end if;
  if not exists (select 1 from public.account_heads where school_id = sid) then
    insert into public.account_heads (school_id, name, kind)
    select sid, x.n, x.k from (values
      ('Donations', 'income'), ('Sale of books & uniform', 'income'), ('Canteen / stationery sales', 'income'), ('Rent received', 'income'),
      ('Event & function income', 'income'), ('Interest received', 'income'), ('Other income', 'income'),
      ('Electricity & water', 'expense'), ('Repairs & maintenance', 'expense'), ('Stationery & printing', 'expense'), ('Fuel & vehicle running', 'expense'),
      ('Teaching aids & books', 'expense'), ('Events & functions', 'expense'), ('Telephone & internet', 'expense'), ('Rent paid', 'expense'),
      ('Cleaning & security', 'expense'), ('Bank charges', 'expense'), ('Other expense', 'expense')
    ) x(n, k);
  end if;
end $$;
revoke execute on function public._account_defaults(uuid) from public, anon, authenticated;

create or replace function public.ensure_account_defaults(sid uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not (public.has_perm_school(sid, 'accounts.vouchers.view') or public.has_perm_school(sid, 'accounts.books.view')) then raise exception 'not allowed'; end if;
  perform public._account_defaults(sid);
end $$;

-- existing schools get the defaults at once; new ones on first visit
do $$ declare s record; begin for s in select id from public.schools loop perform public._account_defaults(s.id); end loop; end $$;

-- ───────────── The unified ledger (internal) ─────────────
-- Every posted money movement of the school between two dates, whatever created it.
create or replace function public._ledger(sid uuid, d1 date, d2 date)
returns table (entry_key text, on_date date, at timestamptz, dir text, head text, book_id uuid, amount numeric, party text, mode text, ref text, narration text,
               source text, source_id uuid, voucher_no text, by_name text)
language sql stable security definer set search_path = public as $$
  with cb as (select id from public.account_books where school_id = sid and kind = 'cash' and active order by created_at limit 1),
       bb as (select id from public.account_books where school_id = sid and kind = 'bank' and active order by created_at limit 1)
  select 'v:' || v.id, v.date, v.created_at,
         case when v.kind = 'receipt' then 'in' else 'out' end, coalesce(h.name, 'Transfer'), v.book_id, v.amount, v.party, v.mode, v.ref_no, v.narration, 'voucher', v.id, v.no, v.created_by_name
    from public.vouchers v left join public.account_heads h on h.id = v.head_id
   where v.school_id = sid and v.status = 'posted' and v.date between d1 and d2
  union all
  select 'vt:' || v.id, v.date, v.created_at, 'in', 'Transfer in', v.to_book_id, v.amount, v.party, v.mode, v.ref_no, v.narration, 'voucher', v.id, v.no, v.created_by_name
    from public.vouchers v where v.school_id = sid and v.status = 'posted' and v.kind = 'transfer' and v.date between d1 and d2
  union all
  select 'fee:' || p.id, r.paid_on, r.created_at, 'in', 'Fee collection',
         case when p.mode = 'cash' then (select id from cb) else coalesce((select id from bb), (select id from cb)) end,
         p.amount, btrim(concat_ws(' ', s.first_name, s.last_name)), p.mode, r.receipt_no, null, 'fee', r.id, r.receipt_no, r.collected_by
    from public.fee_receipt_payments p
    join public.fee_receipts r on r.id = p.receipt_id
    join public.students s on s.id = r.student_id
   where r.school_id = sid and not r.cancelled and r.paid_on between d1 and d2
  union all
  select 'ref:' || f.id, f.paid_on, f.decided_at, 'out', 'Fee refunds',
         case when coalesce(f.mode, 'cash') = 'cash' then (select id from cb) else coalesce((select id from bb), (select id from cb)) end,
         f.amount, btrim(concat_ws(' ', s.first_name, s.last_name)), coalesce(f.mode, 'cash'), f.reference, f.reason, 'refund', f.id, null, f.requested_by_name
    from public.fee_refunds f join public.students s on s.id = f.student_id
   where f.school_id = sid and f.status = 'paid' and f.paid_on between d1 and d2
  union all
  select 'pay:' || r.id, (r.approved_at at time zone 'Asia/Kolkata')::date, r.approved_at, 'out', 'Salaries', (select id from bb),
         (select coalesce(sum(p.net), 0) from public.payslips p where p.run_id = r.id), 'Staff', 'bank_transfer', to_char(r.month, 'Mon YYYY'), 'Salary for ' || to_char(r.month, 'Mon YYYY'),
         'payroll', r.id, null, null
    from public.payroll_runs r
   where r.school_id = sid and r.status = 'approved' and r.approved_at is not null and (r.approved_at at time zone 'Asia/Kolkata')::date between d1 and d2;
$$;
revoke execute on function public._ledger(uuid, date, date) from public, anon, authenticated;

-- the payroll row above has no book when the school has no bank book: fall back to cash
create or replace function public._ledger_fixed(sid uuid, d1 date, d2 date)
returns table (entry_key text, on_date date, at timestamptz, dir text, head text, book_id uuid, amount numeric, party text, mode text, ref text, narration text,
               source text, source_id uuid, voucher_no text, by_name text)
language sql stable security definer set search_path = public as $$
  select l.entry_key, l.on_date, l.at, l.dir, l.head,
         coalesce(l.book_id, (select id from public.account_books where school_id = sid and active order by (kind = 'cash') desc, created_at limit 1)),
         l.amount, l.party, l.mode, l.ref, l.narration, l.source, l.source_id, l.voucher_no, l.by_name
    from public._ledger(sid, d1, d2) l where l.amount > 0;
$$;
revoke execute on function public._ledger_fixed(uuid, date, date) from public, anon, authenticated;

-- ───────────── Reports ─────────────
create or replace function public.account_daybook(sid uuid, d1 date, d2 date, p_book uuid default null, p_dir text default null, p_head text default null,
                                                  p_source text default null, p_q text default null, p_limit int default 50, p_offset int default 0)
returns table (entry_key text, on_date date, at timestamptz, dir text, head text, book_id uuid, book_name text, amount numeric, party text, mode text, ref text, narration text,
               source text, source_id uuid, voucher_no text, by_name text, total bigint, sum_in numeric, sum_out numeric)
language sql stable security definer set search_path = public as $$
  with l as (
    select x.*, b.name as bname from public._ledger_fixed(sid, d1, d2) x left join public.account_books b on b.id = x.book_id
     where (public.has_perm_school(sid, 'accounts.books.view') or public.has_perm_school(sid, 'accounts.vouchers.view'))
       and (p_book is null or x.book_id = p_book) and (p_dir is null or x.dir = p_dir) and (p_head is null or x.head = p_head) and (p_source is null or x.source = p_source)
       and (nullif(btrim(coalesce(p_q, '')), '') is null
            or concat_ws(' ', x.party, x.ref, x.narration, x.voucher_no, x.head) ilike public.like_escape(btrim(p_q)))
  )
  select l.entry_key, l.on_date, l.at, l.dir, l.head, l.book_id, l.bname, l.amount, l.party, l.mode, l.ref, l.narration, l.source, l.source_id, l.voucher_no, l.by_name,
         count(*) over (), sum(l.amount) filter (where l.dir = 'in') over (), sum(l.amount) filter (where l.dir = 'out') over ()
    from l order by l.on_date, l.at, l.entry_key
   limit least(greatest(coalesce(p_limit, 50), 1), 500) offset greatest(coalesce(p_offset, 0), 0);
$$;

-- opening, receipts, payments and closing of every book for a period
create or replace function public.account_books_summary(sid uuid, d1 date, d2 date)
returns table (book_id uuid, name text, kind text, active boolean, opening numeric, receipts numeric, payments numeric, closing numeric)
language plpgsql stable security definer set search_path = public as $$
begin
  if not (public.has_perm_school(sid, 'accounts.books.view') or public.has_perm_school(sid, 'accounts.vouchers.view')) then return; end if;
  return query
    with l as (select x.book_id, x.on_date, x.dir, x.amount from public._ledger_fixed(sid, date '2000-01-01', d2) x)
    select b.id, b.name, b.kind, b.active,
           b.opening_balance + coalesce(sum(case when l.on_date >= b.opening_date and l.on_date < d1 then (case when l.dir = 'in' then l.amount else -l.amount end) end), 0),
           coalesce(sum(l.amount) filter (where l.dir = 'in' and l.on_date >= greatest(d1, b.opening_date)), 0),
           coalesce(sum(l.amount) filter (where l.dir = 'out' and l.on_date >= greatest(d1, b.opening_date)), 0),
           b.opening_balance + coalesce(sum(case when l.on_date >= b.opening_date then (case when l.dir = 'in' then l.amount else -l.amount end) end), 0)
      from public.account_books b left join l on l.book_id = b.id
     where b.school_id = sid
     group by b.id, b.name, b.kind, b.active, b.opening_balance, b.opening_date, b.created_at
     order by (b.kind = 'cash') desc, b.created_at;
end $$;

-- income and expense by head for a period
create or replace function public.account_head_summary(sid uuid, d1 date, d2 date)
returns table (dir text, head text, entries bigint, total numeric)
language sql stable security definer set search_path = public as $$
  select x.dir, x.head, count(*), sum(x.amount)
    from public._ledger_fixed(sid, d1, d2) x
   where (public.has_perm_school(sid, 'accounts.books.view') or public.has_perm_school(sid, 'accounts.vouchers.view'))
     and x.head not in ('Transfer', 'Transfer in')
   group by x.dir, x.head order by x.dir desc, sum(x.amount) desc;
$$;

-- ───────────── Voucher list (paged) ─────────────
create or replace function public.voucher_list(sid uuid, d1 date, d2 date, p_kind text default null, p_status text default null, p_head uuid default null,
                                               p_book uuid default null, p_q text default null, p_limit int default 25, p_offset int default 0)
returns table (id uuid, no text, date date, kind text, head_name text, book_name text, to_book_name text, amount numeric, party text, mode text, ref_no text, narration text,
               status text, created_by_name text, decided_by_name text, decision_note text, created_at timestamptz, total bigint)
language sql stable security definer set search_path = public as $$
  select v.id, v.no, v.date, v.kind, h.name, b.name, tb.name, v.amount, v.party, v.mode, v.ref_no, v.narration, v.status, v.created_by_name, v.decided_by_name, v.decision_note,
         v.created_at, count(*) over ()
    from public.vouchers v
    join public.account_books b on b.id = v.book_id
    left join public.account_books tb on tb.id = v.to_book_id
    left join public.account_heads h on h.id = v.head_id
   where v.school_id = sid and v.date between d1 and d2
     and (public.has_perm_school(sid, 'accounts.vouchers.view') or public.has_perm_school(sid, 'accounts.books.view'))
     and (p_kind is null or v.kind = p_kind) and (p_status is null or v.status = p_status) and (p_head is null or v.head_id = p_head) and (p_book is null or v.book_id = p_book or v.to_book_id = p_book)
     and (nullif(btrim(coalesce(p_q, '')), '') is null or concat_ws(' ', v.party, v.ref_no, v.narration, v.no, h.name) ilike public.like_escape(btrim(p_q)))
   order by v.date desc, v.created_at desc
   limit least(greatest(coalesce(p_limit, 25), 1), 200) offset greatest(coalesce(p_offset, 0), 0);
$$;

-- ───────────── Writing vouchers ─────────────
create or replace function public.save_voucher(sid uuid, p_id uuid, p_kind text, p_date date, p_head uuid, p_book uuid, p_to_book uuid, p_amount numeric,
                                               p_party text, p_mode text, p_ref text, p_narration text) returns uuid
language plpgsql security definer set search_path = public as $$
declare cfg public.account_settings; old public.vouchers; hk text; st text; n int; nm text; i uuid; me text;
begin
  if auth.uid() is null then raise exception 'not allowed'; end if;
  if p_id is null then
    if not public.has_perm_school(sid, 'accounts.vouchers.create') then raise exception 'not allowed'; end if;
  else
    select * into old from public.vouchers where id = p_id and school_id = sid;
    if old.id is null then raise exception 'Voucher not found.'; end if;
    if not public.has_perm_school(sid, 'accounts.vouchers.edit') then raise exception 'not allowed'; end if;
    if old.status in ('cancelled', 'rejected') then raise exception 'A % voucher cannot be changed.', old.status; end if;
  end if;
  if p_kind not in ('receipt', 'payment', 'transfer') then raise exception 'Choose receipt, payment or transfer.'; end if;
  if p_amount is null or p_amount <= 0 or p_amount > 99999999 then raise exception 'Enter an amount greater than zero.'; end if;
  if p_date is null or p_date > public.today_ist() then raise exception 'The voucher date cannot be in the future.'; end if;
  if p_date < public.today_ist() - 400 then raise exception 'That date is too far in the past.'; end if;
  if not exists (select 1 from public.account_books where id = p_book and school_id = sid and active) then raise exception 'Choose a cash or bank book.'; end if;
  if p_kind = 'transfer' then
    if p_to_book is null or p_to_book = p_book or not exists (select 1 from public.account_books where id = p_to_book and school_id = sid and active) then
      raise exception 'A transfer needs two different books.'; end if;
    p_head := null;
  else
    select kind into hk from public.account_heads where id = p_head and school_id = sid and active;
    if hk is null then raise exception 'Choose a head.'; end if;
    if (p_kind = 'receipt' and hk <> 'income') or (p_kind = 'payment' and hk <> 'expense') then raise exception 'That head does not belong to a %.', p_kind; end if;
    p_to_book := null;
  end if;
  if p_mode is not null and p_mode not in ('cash', 'upi', 'cheque', 'bank_transfer', 'card', 'other') then raise exception 'Unknown payment mode.'; end if;

  perform public._account_defaults(sid);
  select * into cfg from public.account_settings where school_id = sid;
  st := case when cfg.approval_above > 0 and p_amount > cfg.approval_above and p_kind <> 'transfer' and not public.has_perm_school(sid, 'accounts.vouchers.approve') then 'pending' else 'posted' end;
  select coalesce(m.name, 'User') into me from (select (select name from public.school_members where school_id = sid and user_id = auth.uid()) as name) m;

  if p_id is null then
    update public.account_settings set next_no = next_no + 1 where school_id = sid returning next_no - 1 into n;
    nm := (case p_kind when 'receipt' then 'RV' when 'payment' then 'PV' else 'TV' end) || '-' || lpad(n::text, 5, '0');
    insert into public.vouchers (school_id, no, date, kind, head_id, book_id, to_book_id, amount, party, mode, ref_no, narration, status, created_by_name)
    values (sid, nm, p_date, p_kind, p_head, p_book, p_to_book, p_amount, nullif(btrim(coalesce(p_party, '')), ''), p_mode, nullif(btrim(coalesce(p_ref, '')), ''),
            nullif(left(btrim(coalesce(p_narration, '')), 500), ''), st, me) returning id into i;
    return i;
  end if;
  update public.vouchers set date = p_date, kind = p_kind, head_id = p_head, book_id = p_book, to_book_id = p_to_book, amount = p_amount,
         party = nullif(btrim(coalesce(p_party, '')), ''), mode = p_mode, ref_no = nullif(btrim(coalesce(p_ref, '')), ''),
         narration = nullif(left(btrim(coalesce(p_narration, '')), 500), ''), status = st, decided_by_name = null, decided_at = null, decision_note = null
   where id = p_id;
  return p_id;
end $$;

create or replace function public.decide_voucher(vid uuid, p_approve boolean, p_note text default null) returns void
language plpgsql security definer set search_path = public as $$
declare v public.vouchers; me text;
begin
  select * into v from public.vouchers where id = vid;
  if v.id is null or auth.uid() is null or not public.has_perm_school(v.school_id, 'accounts.vouchers.approve') then raise exception 'not allowed'; end if;
  if v.status <> 'pending' then raise exception 'This voucher is not waiting for approval.'; end if;
  if not p_approve and coalesce(btrim(p_note), '') = '' then raise exception 'Give a reason for rejecting.'; end if;
  select name into me from public.school_members where school_id = v.school_id and user_id = auth.uid();
  update public.vouchers set status = case when p_approve then 'posted' else 'rejected' end, decided_by_name = coalesce(me, 'User'), decided_at = now(),
         decision_note = nullif(left(btrim(coalesce(p_note, '')), 300), '') where id = vid;
end $$;

create or replace function public.cancel_voucher(vid uuid, p_reason text) returns void
language plpgsql security definer set search_path = public as $$
declare v public.vouchers; me text;
begin
  select * into v from public.vouchers where id = vid;
  if v.id is null or auth.uid() is null or not public.has_perm_school(v.school_id, 'accounts.vouchers.edit') then raise exception 'not allowed'; end if;
  if v.status in ('cancelled', 'rejected') then raise exception 'This voucher is already %.', v.status; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'Give a reason for cancelling.'; end if;
  select name into me from public.school_members where school_id = v.school_id and user_id = auth.uid();
  update public.vouchers set status = 'cancelled', decided_by_name = coalesce(me, 'User'), decided_at = now(), decision_note = left(btrim(p_reason), 300) where id = vid;
end $$;

-- ───────────── Audit ─────────────
do $$
declare t text;
begin
  foreach t in array array['account_heads', 'account_books', 'account_settings', 'vouchers'] loop
    execute format('drop trigger if exists audit_%1$s on public.%1$I', t);
    execute format('create trigger audit_%1$s after insert or update or delete on public.%1$I for each row execute function public.audit_row()', t);
  end loop;
end $$;

-- ═══════════════════════════════════════════════════════════════════════════
-- Step 21: Timetable (bell schedule, class grid, teacher view, substitutions) and the school calendar (holidays, exams, events).
--   A teacher can never be in two sections in the same period (database-enforced).
--   Holidays reduce the working days used by staff attendance → payroll suggestion.
-- Safe to run again.
-- ═══════════════════════════════════════════════════════════════════════════

create table if not exists public.periods (
  id         uuid primary key default gen_random_uuid(),
  school_id  uuid not null references public.schools(id) on delete cascade,
  no         int  not null check (no between 1 and 20),
  name       text not null check (length(btrim(name)) between 1 and 30),
  start_time time not null,
  end_time   time not null,
  is_break   boolean not null default false,
  unique (school_id, no),
  check (end_time > start_time)
);

create table if not exists public.timetable_slots (
  id         uuid primary key default gen_random_uuid(),
  school_id  uuid not null references public.schools(id) on delete cascade,
  section_id uuid not null references public.sections(id) on delete cascade,
  day        int  not null check (day between 1 and 7),          -- 1 = Monday … 7 = Sunday
  period_id  uuid not null references public.periods(id) on delete cascade,
  subject_id uuid references public.subjects(id) on delete set null,
  staff_id   uuid references public.staff(id) on delete set null,
  room       text,
  unique (section_id, day, period_id)
);
create unique index if not exists timetable_teacher_once on public.timetable_slots (staff_id, day, period_id) where staff_id is not null;
create index if not exists timetable_slots_school on public.timetable_slots (school_id, day);

create table if not exists public.substitutions (
  id                  uuid primary key default gen_random_uuid(),
  school_id           uuid not null references public.schools(id) on delete cascade,
  slot_id             uuid not null references public.timetable_slots(id) on delete cascade,
  on_date             date not null,
  substitute_staff_id uuid not null references public.staff(id) on delete cascade,
  reason              text,
  created_by_name     text,
  created_at          timestamptz not null default now(),
  unique (slot_id, on_date)
);
create index if not exists substitutions_day on public.substitutions (school_id, on_date);

create table if not exists public.school_events (
  id              uuid primary key default gen_random_uuid(),
  school_id       uuid not null references public.schools(id) on delete cascade,
  title           text not null check (length(btrim(title)) between 1 and 120),
  kind            text not null default 'event' check (kind in ('holiday', 'vacation', 'exam', 'ptm', 'event', 'other')),
  start_date      date not null,
  end_date        date not null,
  description     text,
  created_by_name text,
  created_at      timestamptz not null default now(),
  check (end_date >= start_date and end_date - start_date <= 120)
);
create index if not exists school_events_range on public.school_events (school_id, start_date, end_date);

alter table public.periods enable row level security;
alter table public.timetable_slots enable row level security;
alter table public.substitutions enable row level security;
alter table public.school_events enable row level security;

drop policy if exists "read" on public.periods;
create policy "read" on public.periods for select to authenticated using (public.is_member(school_id));
drop policy if exists "write" on public.periods;
create policy "write" on public.periods for all to authenticated
  using (public.has_perm_school(school_id, 'academics.timetable.edit')) with check (public.has_perm_school(school_id, 'academics.timetable.edit'));

drop policy if exists "read" on public.timetable_slots;
create policy "read" on public.timetable_slots for select to authenticated
  using (public.can_section(school_id, 'academics.timetable.view', section_id)
         or exists (select 1 from public.staff s where s.id = staff_id and s.user_id = auth.uid()));
-- slots are written by set_slot / clear_slot / copy_slots only

drop policy if exists "read" on public.substitutions;
create policy "read" on public.substitutions for select to authenticated
  using (public.has_perm_school(school_id, 'academics.timetable.view')
         or exists (select 1 from public.staff s where s.id = substitute_staff_id and s.user_id = auth.uid()));

drop policy if exists "read" on public.school_events;
create policy "read" on public.school_events for select to authenticated using (public.has_perm(school_id, 'comms.calendar.view'));
drop policy if exists "create" on public.school_events;
create policy "create" on public.school_events for insert to authenticated with check (public.has_perm_school(school_id, 'comms.calendar.create'));
drop policy if exists "edit" on public.school_events;
create policy "edit" on public.school_events for update to authenticated
  using (public.has_perm_school(school_id, 'comms.calendar.edit')) with check (public.has_perm_school(school_id, 'comms.calendar.edit'));
drop policy if exists "delete" on public.school_events;
create policy "delete" on public.school_events for delete to authenticated using (public.has_perm_school(school_id, 'comms.calendar.delete'));

-- ───────────── Bell schedule defaults ─────────────
create or replace function public.ensure_timetable_defaults(sid uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not (public.has_perm(sid, 'academics.timetable.view') or public.has_perm(sid, 'comms.calendar.view')) then raise exception 'not allowed'; end if;
  if exists (select 1 from public.periods where school_id = sid) then return; end if;
  insert into public.periods (school_id, no, name, start_time, end_time, is_break) values
    (sid, 1, 'Period 1', '08:00', '08:40', false), (sid, 2, 'Period 2', '08:40', '09:20', false), (sid, 3, 'Period 3', '09:20', '10:00', false),
    (sid, 4, 'Period 4', '10:00', '10:40', false), (sid, 5, 'Lunch', '10:40', '11:10', true), (sid, 6, 'Period 5', '11:10', '11:50', false),
    (sid, 7, 'Period 6', '11:50', '12:30', false), (sid, 8, 'Period 7', '12:30', '13:10', false), (sid, 9, 'Period 8', '13:10', '13:50', false);
end $$;

-- ───────────── Timetable editing ─────────────
create or replace function public.set_slot(sid uuid, p_section uuid, p_day int, p_period uuid, p_subject uuid, p_staff uuid, p_room text) returns uuid
language plpgsql security definer set search_path = public as $$
declare clash record; i uuid; rm text := nullif(left(btrim(coalesce(p_room, '')), 30), '');
begin
  if auth.uid() is null or not public.has_perm_school(sid, 'academics.timetable.edit') then raise exception 'not allowed'; end if;
  if p_day not between 1 and 7 then raise exception 'Unknown day.'; end if;
  if not exists (select 1 from public.sections where id = p_section and school_id = sid) then raise exception 'Section not found.'; end if;
  if not exists (select 1 from public.periods where id = p_period and school_id = sid and not is_break) then raise exception 'Choose a teaching period (not a break).'; end if;
  if p_subject is not null and not exists (select 1 from public.subjects where id = p_subject and school_id = sid) then raise exception 'Subject not found.'; end if;
  if p_staff is not null then
    if not exists (select 1 from public.staff where id = p_staff and school_id = sid and status = 'active') then raise exception 'Teacher not found or no longer working here.'; end if;
    select st.name as tname, c.name as cname, sc.name as sname into clash
      from public.timetable_slots t join public.staff st on st.id = t.staff_id join public.sections sc on sc.id = t.section_id join public.classes c on c.id = sc.class_id
     where t.staff_id = p_staff and t.day = p_day and t.period_id = p_period and t.section_id <> p_section limit 1;
    if clash.tname is not null then raise exception '% already teaches %-% in this period.', clash.tname, clash.cname, clash.sname; end if;
  end if;
  if p_subject is null and p_staff is null and rm is null then
    delete from public.timetable_slots where section_id = p_section and day = p_day and period_id = p_period;
    return null;
  end if;
  insert into public.timetable_slots (school_id, section_id, day, period_id, subject_id, staff_id, room) values (sid, p_section, p_day, p_period, p_subject, p_staff, rm)
  on conflict (section_id, day, period_id) do update set subject_id = excluded.subject_id, staff_id = excluded.staff_id, room = excluded.room
  returning id into i;
  return i;
end $$;

-- copy one day of a section to other days; teacher clashes are skipped (their slot is copied without the teacher)
create or replace function public.copy_day(sid uuid, p_section uuid, p_from int, p_to int[]) returns int
language plpgsql security definer set search_path = public as $$
declare s record; d int; n int := 0;
begin
  if auth.uid() is null or not public.has_perm_school(sid, 'academics.timetable.edit') then raise exception 'not allowed'; end if;
  if not exists (select 1 from public.sections where id = p_section and school_id = sid) then raise exception 'Section not found.'; end if;
  foreach d in array p_to loop
    continue when d = p_from or d not between 1 and 7;
    for s in select * from public.timetable_slots where section_id = p_section and day = p_from loop
      insert into public.timetable_slots (school_id, section_id, day, period_id, subject_id, staff_id, room)
      values (sid, p_section, d, s.period_id, s.subject_id,
              case when s.staff_id is not null and not exists (select 1 from public.timetable_slots t where t.staff_id = s.staff_id and t.day = d and t.period_id = s.period_id) then s.staff_id end, s.room)
      on conflict (section_id, day, period_id) do nothing;
      n := n + 1;
    end loop;
  end loop;
  return n;
end $$;

-- ───────────── Substitutions ─────────────
-- who is free in a period on a date: teaching staff with no slot that weekday/period, no cover already, not on approved leave, not marked absent
create or replace function public.free_staff(sid uuid, on_day date, p_period uuid)
returns table (staff_id uuid, name text, designation text, periods_that_day bigint)
language sql stable security definer set search_path = public as $$
  select s.id, s.name, s.designation,
         (select count(*) from public.timetable_slots t where t.staff_id = s.id and t.day = extract(isodow from on_day)::int)
    from public.staff s
   where s.school_id = sid and s.status = 'active' and s.kind = 'teaching'
     and public.has_perm_school(sid, 'academics.timetable.view')
     and not exists (select 1 from public.timetable_slots t where t.staff_id = s.id and t.day = extract(isodow from on_day)::int and t.period_id = p_period)
     and not exists (select 1 from public.substitutions u join public.timetable_slots t on t.id = u.slot_id
                      where u.substitute_staff_id = s.id and u.on_date = on_day and t.period_id = p_period)
     and not exists (select 1 from public.staff_leaves l where l.staff_id = s.id and l.status = 'approved' and on_day between l.from_date and l.to_date)
     and not exists (select 1 from public.staff_attendance a where a.staff_id = s.id and a.date = on_day and a.status in ('A', 'LV'))
   order by 4, s.name;
$$;

-- periods that need cover on a date (the teacher is on leave or marked absent)
create or replace function public.cover_needed(sid uuid, on_day date)
returns table (slot_id uuid, class_name text, section_name text, period_id uuid, period_name text, start_time time, end_time time, subject_name text,
               teacher_id uuid, teacher_name text, why text, substitution_id uuid, substitute_id uuid, substitute_name text)
language sql stable security definer set search_path = public as $$
  select t.id, c.name, sc.name, p.id, p.name, p.start_time, p.end_time, sj.name, st.id, st.name,
         coalesce((select 'On ' || l.kind || ' leave' from public.staff_leaves l where l.staff_id = st.id and l.status = 'approved' and on_day between l.from_date and l.to_date limit 1), 'Marked absent'),
         u.id, u.substitute_staff_id, ss.name
    from public.timetable_slots t
    join public.periods p on p.id = t.period_id
    join public.sections sc on sc.id = t.section_id
    join public.classes c on c.id = sc.class_id
    join public.staff st on st.id = t.staff_id
    left join public.subjects sj on sj.id = t.subject_id
    left join public.substitutions u on u.slot_id = t.id and u.on_date = on_day
    left join public.staff ss on ss.id = u.substitute_staff_id
   where t.school_id = sid and t.day = extract(isodow from on_day)::int
     and public.has_perm_school(sid, 'academics.timetable.view')
     and (exists (select 1 from public.staff_leaves l where l.staff_id = st.id and l.status = 'approved' and on_day between l.from_date and l.to_date and not l.half_day)
          or exists (select 1 from public.staff_attendance a where a.staff_id = st.id and a.date = on_day and a.status in ('A', 'LV')))
   order by p.no, c.sort, sc.name;
$$;

create or replace function public.save_substitution(sid uuid, p_slot uuid, p_date date, p_staff uuid, p_reason text) returns uuid
language plpgsql security definer set search_path = public as $$
declare t public.timetable_slots; me text; i uuid;
begin
  if auth.uid() is null or not public.has_perm_school(sid, 'academics.timetable.edit') then raise exception 'not allowed'; end if;
  select * into t from public.timetable_slots where id = p_slot and school_id = sid;
  if t.id is null then raise exception 'That period was not found.'; end if;
  if p_date is null or p_date < public.today_ist() - 7 or p_date > public.today_ist() + 60 then raise exception 'Choose a date within the next 60 days.'; end if;
  if extract(isodow from p_date)::int <> t.day then raise exception 'That date is not a %.', trim(to_char(date '2024-01-01' + (t.day - 1), 'Day')); end if;
  if p_staff = t.staff_id then raise exception 'The substitute is the same teacher.'; end if;
  if not exists (select 1 from public.free_staff(sid, p_date, t.period_id) f where f.staff_id = p_staff) then raise exception 'That teacher is not free in this period.'; end if;
  select name into me from public.school_members where school_id = sid and user_id = auth.uid();
  insert into public.substitutions (school_id, slot_id, on_date, substitute_staff_id, reason, created_by_name)
  values (sid, p_slot, p_date, p_staff, nullif(left(btrim(coalesce(p_reason, '')), 200), ''), coalesce(me, 'User'))
  on conflict (slot_id, on_date) do update set substitute_staff_id = excluded.substitute_staff_id, reason = excluded.reason, created_by_name = excluded.created_by_name
  returning id into i;
  return i;
end $$;

create or replace function public.remove_substitution(sub uuid) returns void
language plpgsql security definer set search_path = public as $$
declare s public.substitutions;
begin
  select * into s from public.substitutions where id = sub;
  if s.id is null or not public.has_perm_school(s.school_id, 'academics.timetable.edit') then raise exception 'not allowed'; end if;
  delete from public.substitutions where id = sub;
end $$;

-- weekly load per teacher
create or replace function public.teacher_load(sid uuid)
returns table (staff_id uuid, name text, designation text, periods bigint, sections bigint, subjects bigint, busiest_day int, busiest_count bigint)
language sql stable security definer set search_path = public as $$
  with per as (select t.staff_id, t.day, count(*) c from public.timetable_slots t where t.school_id = sid and t.staff_id is not null group by 1, 2),
       top as (select distinct on (staff_id) staff_id, day, c from per order by staff_id, c desc, day)
  select s.id, s.name, s.designation,
         coalesce((select count(*) from public.timetable_slots t where t.staff_id = s.id), 0),
         coalesce((select count(distinct t.section_id) from public.timetable_slots t where t.staff_id = s.id), 0),
         coalesce((select count(distinct t.subject_id) from public.timetable_slots t where t.staff_id = s.id), 0),
         top.day, top.c
    from public.staff s left join top on top.staff_id = s.id
   where s.school_id = sid and s.status = 'active' and s.kind = 'teaching' and public.has_perm_school(sid, 'academics.timetable.view')
   order by 4 desc, s.name;
$$;

-- ───────────── Calendar helpers ─────────────
-- the holiday or vacation covering a date, if any
create or replace function public.holiday_on(sid uuid, on_day date) returns text
language sql stable security definer set search_path = public as $$
  select e.title from public.school_events e
   where e.school_id = sid and e.kind in ('holiday', 'vacation') and on_day between e.start_date and e.end_date
     and (public.has_perm(sid, 'comms.calendar.view') or public.has_perm(sid, 'attendance.students.view') or public.has_perm(sid, 'attendance.staff.view'))
   order by e.start_date limit 1;
$$;

-- staff attendance month summary: working days now exclude holidays and vacations
create or replace function public.staff_attendance_month(sid uuid, p_month date)
returns table (staff_id uuid, name text, emp_code text, present numeric, late bigint, half bigint, absent bigint, leave_days numeric, on_duty bigint, marked bigint, working_days int, suggested_lop numeric)
language plpgsql stable security definer set search_path = public as $$
declare m1 date := date_trunc('month', p_month)::date; m2 date := (date_trunc('month', p_month) + interval '1 month - 1 day')::date; wd int; days int[];
begin
  if not public.has_perm_school(sid, 'attendance.staff.view') then return; end if;
  select coalesce(array(select jsonb_array_elements_text(prefs -> 'working_days')::int), array[1,2,3,4,5,6]) into days from public.schools where id = sid;
  if days is null or cardinality(days) = 0 then days := array[1,2,3,4,5,6]; end if;
  select count(*) into wd from generate_series(m1, m2, interval '1 day') g
   where extract(isodow from g)::int = any(days)
     and not exists (select 1 from public.school_events e where e.school_id = sid and e.kind in ('holiday', 'vacation') and g::date between e.start_date and e.end_date);
  return query
    select s.id, s.name, s.emp_code,
           coalesce(sum(case when a.status in ('P', 'L', 'OD') then 1 when a.status = 'H' then 0.5 else 0 end), 0),
           count(*) filter (where a.status = 'L'), count(*) filter (where a.status = 'H'), count(*) filter (where a.status = 'A'),
           coalesce((select sum(l.days) from public.staff_leaves l where l.staff_id = s.id and l.status = 'approved' and l.kind <> 'LWP' and l.from_date <= m2 and l.to_date >= m1), 0)::numeric,
           count(*) filter (where a.status = 'OD'), count(a.id), wd,
           greatest(wd - coalesce(sum(case when a.status in ('P', 'L', 'OD') then 1 when a.status = 'H' then 0.5 else 0 end), 0)
                       - coalesce((select sum(l.days) from public.staff_leaves l where l.staff_id = s.id and l.status = 'approved' and l.kind <> 'LWP' and l.from_date <= m2 and l.to_date >= m1), 0), 0)::numeric
      from public.staff s left join public.staff_attendance a on a.staff_id = s.id and a.date between m1 and m2
     where s.school_id = sid and s.status = 'active'
     group by s.id, s.name, s.emp_code
     order by s.name;
end $$;

-- ───────────── Audit ─────────────
do $$
declare t text;
begin
  foreach t in array array['periods', 'timetable_slots', 'substitutions', 'school_events'] loop
    execute format('drop trigger if exists audit_%1$s on public.%1$I', t);
    execute format('create trigger audit_%1$s after insert or update or delete on public.%1$I for each row execute function public.audit_row()', t);
  end loop;
end $$;

-- ═══════════════════════════════════════════════════════════════════════════
-- Step 22: Front office — visitor log with passes, phone call log with follow-ups, postal register, student gate pass
--          (early leave with a named pick-up person), and one "today at the front desk" summary.
-- Safe to run again.
-- ═══════════════════════════════════════════════════════════════════════════

create table if not exists public.front_office_settings (
  school_id uuid primary key references public.schools(id) on delete cascade,
  next_visitor_no int not null default 1,
  next_pass_no int not null default 1
);
alter table public.front_office_settings enable row level security;
drop policy if exists "read" on public.front_office_settings;
create policy "read" on public.front_office_settings for select to authenticated using (public.has_perm(school_id, 'frontdesk.visitors.view'));

-- ───────────── Visitors ─────────────
create table if not exists public.visitors (
  id              uuid primary key default gen_random_uuid(),
  school_id       uuid not null references public.schools(id) on delete cascade,
  pass_no         text not null,
  name            text not null check (length(btrim(name)) between 1 and 80),
  phone           text,
  purpose         text not null default 'meeting' check (purpose in ('meeting', 'admission', 'parent', 'vendor', 'official', 'interview', 'delivery', 'other')),
  to_meet         text,
  student_id      uuid references public.students(id) on delete set null,
  organisation    text,
  id_proof        text,
  people          int not null default 1 check (people between 1 and 50),
  vehicle_no      text,
  note            text,
  in_at           timestamptz not null default now(),
  out_at          timestamptz,
  created_by_name text,
  unique (school_id, pass_no),
  check (out_at is null or out_at >= in_at)
);
create index if not exists visitors_day on public.visitors (school_id, in_at desc);
create index if not exists visitors_inside on public.visitors (school_id) where out_at is null;

-- ───────────── Calls ─────────────
create table if not exists public.phone_calls (
  id              uuid primary key default gen_random_uuid(),
  school_id       uuid not null references public.schools(id) on delete cascade,
  direction       text not null default 'incoming' check (direction in ('incoming', 'outgoing')),
  name            text,
  phone           text,
  purpose         text not null default 'enquiry' check (purpose in ('enquiry', 'complaint', 'fees', 'leave', 'transport', 'staff', 'other')),
  summary         text,
  student_id      uuid references public.students(id) on delete set null,
  call_at         timestamptz not null default now(),
  follow_up_on    date,
  followed_up_at  timestamptz,
  handled_by_name text,
  created_at      timestamptz not null default now()
);
create index if not exists phone_calls_day on public.phone_calls (school_id, call_at desc);
create index if not exists phone_calls_followup on public.phone_calls (school_id, follow_up_on) where follow_up_on is not null and followed_up_at is null;

-- ───────────── Postal register ─────────────
create table if not exists public.postal_items (
  id              uuid primary key default gen_random_uuid(),
  school_id       uuid not null references public.schools(id) on delete cascade,
  direction       text not null check (direction in ('received', 'dispatched')),
  on_date         date not null default (now() at time zone 'Asia/Kolkata')::date,
  mode            text not null default 'post' check (mode in ('post', 'speed_post', 'courier', 'hand', 'other')),
  party           text not null check (length(btrim(party)) > 0),
  reference_no    text,
  subject         text,
  to_whom         text,
  note            text,
  created_by_name text,
  created_at      timestamptz not null default now()
);
create index if not exists postal_day on public.postal_items (school_id, on_date desc);

-- ───────────── Student gate pass (early leave) ─────────────
create table if not exists public.gate_passes (
  id               uuid primary key default gen_random_uuid(),
  school_id        uuid not null references public.schools(id) on delete cascade,
  pass_no          text not null,
  student_id       uuid not null references public.students(id) on delete cascade,
  reason           text not null check (length(btrim(reason)) > 0),
  leave_on         date not null default (now() at time zone 'Asia/Kolkata')::date,
  pickup_name      text not null,
  pickup_relation  text,
  pickup_phone     text,
  status           text not null default 'requested' check (status in ('requested', 'approved', 'rejected', 'completed', 'cancelled')),
  requested_by_name text,
  decided_by_name  text,
  decided_at       timestamptz,
  decision_note    text,
  out_at           timestamptz,
  created_at       timestamptz not null default now(),
  unique (school_id, pass_no)
);
create index if not exists gate_passes_day on public.gate_passes (school_id, leave_on desc, status);

alter table public.visitors enable row level security;
alter table public.phone_calls enable row level security;
alter table public.postal_items enable row level security;
alter table public.gate_passes enable row level security;

do $$
declare t text;
begin
  foreach t in array array['visitors', 'phone_calls', 'postal_items'] loop
    execute format('drop policy if exists "read" on public.%I', t);
    execute format('create policy "read" on public.%I for select to authenticated using (public.has_perm_school(school_id, ''frontdesk.visitors.view''))', t);
    execute format('drop policy if exists "create" on public.%I', t);
    execute format('create policy "create" on public.%I for insert to authenticated with check (public.has_perm_school(school_id, ''frontdesk.visitors.create''))', t);
    execute format('drop policy if exists "edit" on public.%I', t);
    execute format('create policy "edit" on public.%I for update to authenticated using (public.has_perm_school(school_id, ''frontdesk.visitors.edit'')) with check (public.has_perm_school(school_id, ''frontdesk.visitors.edit''))', t);
    execute format('drop policy if exists "delete" on public.%I', t);
    execute format('create policy "delete" on public.%I for delete to authenticated using (public.has_perm_school(school_id, ''frontdesk.visitors.delete''))', t);
  end loop;
end $$;
drop policy if exists "read" on public.gate_passes;
create policy "read" on public.gate_passes for select to authenticated using (public.has_perm_school(school_id, 'frontdesk.visitors.view'));
-- gate passes are written by the functions below

-- ───────────── Numbers ─────────────
create or replace function public._fo_number(sid uuid, what text) returns text
language plpgsql security definer set search_path = public as $$
declare n int;
begin
  insert into public.front_office_settings (school_id) values (sid) on conflict do nothing;
  if what = 'visitor' then
    update public.front_office_settings set next_visitor_no = next_visitor_no + 1 where school_id = sid returning next_visitor_no - 1 into n;
    return 'V-' || to_char((now() at time zone 'Asia/Kolkata'), 'YYMM') || '-' || lpad(n::text, 4, '0');
  end if;
  update public.front_office_settings set next_pass_no = next_pass_no + 1 where school_id = sid returning next_pass_no - 1 into n;
  return 'GP-' || to_char((now() at time zone 'Asia/Kolkata'), 'YYMM') || '-' || lpad(n::text, 4, '0');
end $$;
revoke execute on function public._fo_number(uuid, text) from public, anon, authenticated;

-- ───────────── Visitors ─────────────
create or replace function public.visitor_checkin(sid uuid, p_name text, p_phone text, p_purpose text, p_to_meet text, p_student uuid, p_org text,
                                                  p_id_proof text, p_people int, p_vehicle text, p_note text) returns uuid
language plpgsql security definer set search_path = public as $$
declare i uuid; me text;
begin
  if auth.uid() is null or not public.has_perm_school(sid, 'frontdesk.visitors.create') then raise exception 'not allowed'; end if;
  if coalesce(btrim(p_name), '') = '' then raise exception 'Enter the visitor''s name.'; end if;
  if p_phone is not null and btrim(p_phone) <> '' and btrim(p_phone) !~ '^[0-9+() -]{6,20}$' then raise exception 'That phone number does not look right.'; end if;
  if p_student is not null and not exists (select 1 from public.students where id = p_student and school_id = sid) then raise exception 'Student not found.'; end if;
  select name into me from public.school_members where school_id = sid and user_id = auth.uid();
  insert into public.visitors (school_id, pass_no, name, phone, purpose, to_meet, student_id, organisation, id_proof, people, vehicle_no, note, created_by_name)
  values (sid, public._fo_number(sid, 'visitor'), left(btrim(p_name), 80), nullif(btrim(coalesce(p_phone, '')), ''), coalesce(nullif(p_purpose, ''), 'meeting'),
          nullif(left(btrim(coalesce(p_to_meet, '')), 80), ''), p_student, nullif(left(btrim(coalesce(p_org, '')), 80), ''), nullif(left(btrim(coalesce(p_id_proof, '')), 60), ''),
          greatest(coalesce(p_people, 1), 1), nullif(left(btrim(coalesce(p_vehicle, '')), 20), ''), nullif(left(btrim(coalesce(p_note, '')), 300), ''), coalesce(me, 'User'))
  returning id into i;
  return i;
end $$;

create or replace function public.visitor_checkout(vid uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v public.visitors;
begin
  select * into v from public.visitors where id = vid;
  if v.id is null or auth.uid() is null or not public.has_perm_school(v.school_id, 'frontdesk.visitors.create') then raise exception 'not allowed'; end if;
  if v.out_at is not null then raise exception 'This visitor has already left.'; end if;
  update public.visitors set out_at = now() where id = vid;
end $$;

create or replace function public.visitor_list(sid uuid, d1 date, d2 date, p_q text default null, p_purpose text default null, p_inside boolean default null,
                                               p_limit int default 25, p_offset int default 0)
returns table (id uuid, pass_no text, name text, phone text, purpose text, to_meet text, student_name text, organisation text, id_proof text, people int, vehicle_no text, note text,
               in_at timestamptz, out_at timestamptz, created_by_name text, total bigint)
language sql stable security definer set search_path = public as $$
  select v.id, v.pass_no, v.name, v.phone, v.purpose, v.to_meet, btrim(concat_ws(' ', s.first_name, s.last_name)), v.organisation, v.id_proof, v.people, v.vehicle_no, v.note,
         v.in_at, v.out_at, v.created_by_name, count(*) over ()
    from public.visitors v left join public.students s on s.id = v.student_id
   where v.school_id = sid and public.has_perm_school(sid, 'frontdesk.visitors.view')
     and (v.in_at at time zone 'Asia/Kolkata')::date between d1 and d2
     and (p_purpose is null or v.purpose = p_purpose)
     and (p_inside is null or (p_inside and v.out_at is null) or (not p_inside and v.out_at is not null))
     and (nullif(btrim(coalesce(p_q, '')), '') is null or concat_ws(' ', v.name, v.phone, v.pass_no, v.to_meet, v.organisation, v.vehicle_no) ilike public.like_escape(btrim(p_q)))
   order by v.in_at desc
   limit least(greatest(coalesce(p_limit, 25), 1), 200) offset greatest(coalesce(p_offset, 0), 0);
$$;

-- ───────────── Gate pass ─────────────
create or replace function public.gate_pass_request(sid uuid, p_student uuid, p_reason text, p_pickup text, p_relation text, p_phone text) returns uuid
language plpgsql security definer set search_path = public as $$
declare st record; i uuid; me text; auto boolean;
begin
  if auth.uid() is null or not public.has_perm_school(sid, 'frontdesk.visitors.create') then raise exception 'not allowed'; end if;
  select id, status into st from public.students where id = p_student and school_id = sid;
  if st.id is null then raise exception 'Student not found.'; end if;
  if st.status <> 'active' then raise exception 'This student is not on roll.'; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'Give the reason for leaving early.'; end if;
  if coalesce(btrim(p_pickup), '') = '' then raise exception 'Name the person who will take the child.'; end if;
  if exists (select 1 from public.gate_passes where student_id = p_student and leave_on = public.today_ist() and status in ('requested', 'approved')) then
    raise exception 'There is already an open gate pass for this student today.'; end if;
  select name into me from public.school_members where school_id = sid and user_id = auth.uid();
  auto := public.has_perm_school(sid, 'frontdesk.visitors.edit');
  insert into public.gate_passes (school_id, pass_no, student_id, reason, pickup_name, pickup_relation, pickup_phone, status, requested_by_name, decided_by_name, decided_at)
  values (sid, public._fo_number(sid, 'pass'), p_student, left(btrim(p_reason), 200), left(btrim(p_pickup), 80), nullif(left(btrim(coalesce(p_relation, '')), 40), ''),
          nullif(left(btrim(coalesce(p_phone, '')), 20), ''), case when auto then 'approved' else 'requested' end, coalesce(me, 'User'),
          case when auto then coalesce(me, 'User') end, case when auto then now() end)
  returning id into i;
  return i;
end $$;

create or replace function public.gate_pass_decide(gid uuid, p_approve boolean, p_note text default null) returns void
language plpgsql security definer set search_path = public as $$
declare g public.gate_passes; me text;
begin
  select * into g from public.gate_passes where id = gid;
  if g.id is null or auth.uid() is null or not public.has_perm_school(g.school_id, 'frontdesk.visitors.edit') then raise exception 'not allowed'; end if;
  if g.status <> 'requested' then raise exception 'This pass is already %.', g.status; end if;
  if not p_approve and coalesce(btrim(p_note), '') = '' then raise exception 'Give a reason for refusing.'; end if;
  select name into me from public.school_members where school_id = g.school_id and user_id = auth.uid();
  update public.gate_passes set status = case when p_approve then 'approved' else 'rejected' end, decided_by_name = coalesce(me, 'User'), decided_at = now(),
         decision_note = nullif(left(btrim(coalesce(p_note, '')), 200), '') where id = gid;
end $$;

-- the child actually leaves: records the out-time on today's attendance
create or replace function public.gate_pass_complete(gid uuid) returns void
language plpgsql security definer set search_path = public as $$
declare g public.gate_passes; tm time := date_trunc('second', (now() at time zone 'Asia/Kolkata'))::time;
begin
  select * into g from public.gate_passes where id = gid;
  if g.id is null or auth.uid() is null or not public.has_perm_school(g.school_id, 'frontdesk.visitors.create') then raise exception 'not allowed'; end if;
  if g.status <> 'approved' then raise exception 'Only an approved pass can be used.'; end if;
  if g.leave_on <> public.today_ist() then raise exception 'This pass was for %.', to_char(g.leave_on, 'DD Mon'); end if;
  update public.gate_passes set status = 'completed', out_at = now() where id = gid;
  update public.attendance set out_time = tm, note = coalesce(note || ' · ', '') || 'Left early (gate pass ' || g.pass_no || ')'
   where student_id = g.student_id and date = g.leave_on;
end $$;

create or replace function public.gate_pass_cancel(gid uuid) returns void
language plpgsql security definer set search_path = public as $$
declare g public.gate_passes;
begin
  select * into g from public.gate_passes where id = gid;
  if g.id is null or auth.uid() is null or not public.has_perm_school(g.school_id, 'frontdesk.visitors.create') then raise exception 'not allowed'; end if;
  if g.status not in ('requested', 'approved') then raise exception 'This pass is already %.', g.status; end if;
  update public.gate_passes set status = 'cancelled' where id = gid;
end $$;

-- ───────────── Calls ─────────────
create or replace function public.call_followup_done(cid uuid) returns void
language plpgsql security definer set search_path = public as $$
declare c public.phone_calls;
begin
  select * into c from public.phone_calls where id = cid;
  if c.id is null or auth.uid() is null or not public.has_perm_school(c.school_id, 'frontdesk.visitors.edit') then raise exception 'not allowed'; end if;
  update public.phone_calls set followed_up_at = now() where id = cid and followed_up_at is null;
end $$;

-- ───────────── Today at the front desk ─────────────
create or replace function public.frontdesk_today(sid uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare d date := public.today_ist();
begin
  if not (public.has_perm_school(sid, 'frontdesk.visitors.view') or public.has_perm_school(sid, 'frontdesk.enquiries.view') or public.has_perm_school(sid, 'frontdesk.admissions.view')) then
    raise exception 'not allowed'; end if;
  return jsonb_build_object(
    'visitors_today', (select count(*) from public.visitors where school_id = sid and (in_at at time zone 'Asia/Kolkata')::date = d),
    'visitors_inside', (select count(*) from public.visitors where school_id = sid and out_at is null and (in_at at time zone 'Asia/Kolkata')::date >= d - 1),
    'calls_today', (select count(*) from public.phone_calls where school_id = sid and (call_at at time zone 'Asia/Kolkata')::date = d),
    'followups_due', (select count(*) from public.phone_calls where school_id = sid and follow_up_on <= d and followed_up_at is null),
    'passes_waiting', (select count(*) from public.gate_passes where school_id = sid and status = 'requested'),
    'passes_to_release', (select count(*) from public.gate_passes where school_id = sid and status = 'approved' and leave_on = d),
    'postal_today', (select count(*) from public.postal_items where school_id = sid and on_date = d),
    'enquiries_new', (select count(*) from public.enquiries where school_id = sid and status = 'new'),
    'applications_open', (select count(*) from public.admission_applications where school_id = sid and status not in ('admitted', 'rejected', 'cancelled'))
  );
end $$;

-- ───────────── Audit ─────────────
do $$
declare t text;
begin
  foreach t in array array['visitors', 'phone_calls', 'postal_items', 'gate_passes'] loop
    execute format('drop trigger if exists audit_%1$s on public.%1$I', t);
    execute format('create trigger audit_%1$s after insert or update or delete on public.%1$I for each row execute function public.audit_row()', t);
  end loop;
end $$;

-- ═══════════════════════════════════════════════════════════════════════════
-- Step 23: Academic setup — curriculum (which subjects each class studies, periods a week, optional), section capacity and room,
--          class teacher / subject teacher allocation in one place, syllabus & lesson-plan tracking with coverage.
-- Safe to run again.
-- ═══════════════════════════════════════════════════════════════════════════

alter table public.sections add column if not exists capacity int check (capacity is null or capacity between 1 and 200);
alter table public.sections add column if not exists room text;

create table if not exists public.class_subjects (
  id               uuid primary key default gen_random_uuid(),
  school_id        uuid not null references public.schools(id) on delete cascade,
  class_id         uuid not null references public.classes(id) on delete cascade,
  subject_id       uuid not null references public.subjects(id) on delete cascade,
  periods_per_week int not null default 5 check (periods_per_week between 0 and 20),
  is_optional      boolean not null default false,
  unique (class_id, subject_id)
);
create index if not exists class_subjects_school on public.class_subjects (school_id);

create table if not exists public.syllabus_units (
  id               uuid primary key default gen_random_uuid(),
  school_id        uuid not null references public.schools(id) on delete cascade,
  session_id       uuid not null references public.sessions(id) on delete cascade,
  class_id         uuid not null references public.classes(id) on delete cascade,
  subject_id       uuid not null references public.subjects(id) on delete cascade,
  no               int not null default 1,
  title            text not null check (length(btrim(title)) between 1 and 160),
  term             text,
  planned_on       date,
  status           text not null default 'pending' check (status in ('pending', 'in_progress', 'done')),
  completed_on     date,
  note             text,
  verified_by_name text,
  verified_at      timestamptz,
  updated_by_name  text,
  created_at       timestamptz not null default now()
);
create index if not exists syllabus_units_idx on public.syllabus_units (school_id, session_id, class_id, subject_id, no);

alter table public.class_subjects enable row level security;
alter table public.syllabus_units enable row level security;

drop policy if exists "read" on public.class_subjects;
create policy "read" on public.class_subjects for select to authenticated using (public.is_member(school_id));
drop policy if exists "write" on public.class_subjects;
create policy "write" on public.class_subjects for all to authenticated
  using (public.has_perm_school(school_id, 'academics.setup.edit')) with check (public.has_perm_school(school_id, 'academics.setup.edit'));

-- may this user write syllabus rows of this class + subject?
create or replace function public.can_syllabus(sid uuid, p_class uuid, p_subject uuid, pkey text) returns boolean
language plpgsql stable security definer set search_path = public as $$
declare s text := public.perm_scope(sid, pkey);
begin
  if s = 'school' then return true; end if;
  if s = 'assigned' then
    return exists (select 1 from public.staff_assignments a join public.sections sc on sc.id = a.section_id
                    where a.school_id = sid and a.user_id = auth.uid() and sc.class_id = p_class and (a.subject_id is null or a.subject_id = p_subject));
  end if;
  return false;
end $$;

drop policy if exists "read" on public.syllabus_units;
create policy "read" on public.syllabus_units for select to authenticated
  using (public.has_perm_school(school_id, 'academics.syllabus.view') or public.can_syllabus(school_id, class_id, subject_id, 'academics.syllabus.view'));
drop policy if exists "create" on public.syllabus_units;
create policy "create" on public.syllabus_units for insert to authenticated with check (public.can_syllabus(school_id, class_id, subject_id, 'academics.syllabus.create'));
drop policy if exists "edit" on public.syllabus_units;
create policy "edit" on public.syllabus_units for update to authenticated
  using (public.can_syllabus(school_id, class_id, subject_id, 'academics.syllabus.edit')) with check (public.can_syllabus(school_id, class_id, subject_id, 'academics.syllabus.edit'));
drop policy if exists "delete" on public.syllabus_units;
create policy "delete" on public.syllabus_units for delete to authenticated using (public.can_syllabus(school_id, class_id, subject_id, 'academics.syllabus.delete'));

-- stamps who changed a unit; completion date follows status; a changed unit loses its verification
create or replace function public.syllabus_unit_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare me text;
begin
  select name into me from public.school_members where school_id = new.school_id and user_id = auth.uid();
  new.updated_by_name := coalesce(me, new.updated_by_name);
  if new.status = 'done' and new.completed_on is null then new.completed_on := public.today_ist(); end if;
  if new.status <> 'done' then new.completed_on := null; end if;
  if tg_op = 'UPDATE' and (new.status is distinct from old.status or new.title is distinct from old.title) and new.verified_at is not distinct from old.verified_at then
    new.verified_by_name := null; new.verified_at := null;
  end if;
  return new;
end $$;
drop trigger if exists syllabus_unit_guard on public.syllabus_units;
create trigger syllabus_unit_guard before insert or update on public.syllabus_units for each row execute function public.syllabus_unit_guard();

create or replace function public.verify_syllabus_unit(uid2 uuid, p_ok boolean default true) returns void
language plpgsql security definer set search_path = public as $$
declare u public.syllabus_units; me text;
begin
  select * into u from public.syllabus_units where id = uid2;
  if u.id is null or auth.uid() is null or not public.has_perm_school(u.school_id, 'academics.syllabus.approve') then raise exception 'not allowed'; end if;
  if u.status <> 'done' then raise exception 'Only a completed unit can be verified.'; end if;
  select name into me from public.school_members where school_id = u.school_id and user_id = auth.uid();
  update public.syllabus_units set verified_by_name = case when p_ok then coalesce(me, 'User') end, verified_at = case when p_ok then now() end where id = uid2;
end $$;

-- ───────────── Overview, allocation, progress ─────────────
create or replace function public.academic_overview(sid uuid)
returns table (class_id uuid, class_name text, class_sort int, section_id uuid, section_name text, capacity int, room text, students bigint,
               class_teacher_id uuid, class_teacher_name text, subjects_mapped bigint, subjects_staffed bigint)
language sql stable security definer set search_path = public as $$
  select c.id, c.name, c.sort, s.id, s.name, s.capacity, s.room,
         (select count(*) from public.students st where st.section_id = s.id and st.status = 'active'),
         ct.user_id, (select m.name from public.school_members m where m.school_id = sid and m.user_id = ct.user_id),
         (select count(*) from public.class_subjects cs where cs.class_id = c.id),
         (select count(distinct a.subject_id) from public.staff_assignments a join public.class_subjects cs on cs.subject_id = a.subject_id and cs.class_id = c.id where a.section_id = s.id)
    from public.classes c
    join public.sections s on s.class_id = c.id
    left join lateral (select a.user_id from public.staff_assignments a where a.section_id = s.id and a.is_class_teacher limit 1) ct on true
   where c.school_id = sid and public.is_member(sid)
   order by c.sort, c.name, s.name;
$$;

create or replace function public.set_class_teacher(sid uuid, p_section uuid, p_user uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null or not (public.has_perm_school(sid, 'academics.allocation.edit') or public.has_perm_school(sid, 'academics.allocation.create')) then raise exception 'not allowed'; end if;
  if not exists (select 1 from public.sections where id = p_section and school_id = sid) then raise exception 'Section not found.'; end if;
  if p_user is not null and not exists (select 1 from public.school_members where school_id = sid and user_id = p_user) then raise exception 'That person does not have a login in this school.'; end if;
  delete from public.staff_assignments where section_id = p_section and is_class_teacher;
  update public.sections set class_teacher_id = p_user where id = p_section;
  if p_user is not null then
    delete from public.staff_assignments where section_id = p_section and user_id = p_user and subject_id is null;
    insert into public.staff_assignments (school_id, user_id, section_id, subject_id, is_class_teacher) values (sid, p_user, p_section, null, true);
  end if;
end $$;

create or replace function public.set_subject_teacher(sid uuid, p_section uuid, p_subject uuid, p_user uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null or not (public.has_perm_school(sid, 'academics.allocation.edit') or public.has_perm_school(sid, 'academics.allocation.create')) then raise exception 'not allowed'; end if;
  if not exists (select 1 from public.sections where id = p_section and school_id = sid) then raise exception 'Section not found.'; end if;
  if not exists (select 1 from public.subjects where id = p_subject and school_id = sid) then raise exception 'Subject not found.'; end if;
  if p_user is not null and not exists (select 1 from public.school_members where school_id = sid and user_id = p_user) then raise exception 'That person does not have a login in this school.'; end if;
  delete from public.staff_assignments where section_id = p_section and subject_id = p_subject and not is_class_teacher;
  if p_user is not null then
    insert into public.staff_assignments (school_id, user_id, section_id, subject_id, is_class_teacher) values (sid, p_user, p_section, p_subject, false)
    on conflict do nothing;
  end if;
end $$;

create or replace function public.syllabus_progress(sid uuid, p_session uuid, p_class uuid default null)
returns table (class_id uuid, class_name text, class_sort int, subject_id uuid, subject_name text, units bigint, in_progress bigint, done bigint, verified bigint, pct numeric)
language sql stable security definer set search_path = public as $$
  select c.id, c.name, c.sort, s.id, s.name, count(u.id), count(u.id) filter (where u.status = 'in_progress'), count(u.id) filter (where u.status = 'done'),
         count(u.id) filter (where u.verified_at is not null), round(100.0 * count(u.id) filter (where u.status = 'done') / nullif(count(u.id), 0), 0)
    from public.class_subjects cs
    join public.classes c on c.id = cs.class_id
    join public.subjects s on s.id = cs.subject_id
    left join public.syllabus_units u on u.class_id = c.id and u.subject_id = s.id and u.session_id = p_session
   where cs.school_id = sid and (p_class is null or c.id = p_class)
     and (public.has_perm(sid, 'academics.syllabus.view') or public.has_perm(sid, 'academics.setup.view'))
   group by c.id, c.name, c.sort, s.id, s.name
   order by c.sort, s.name;
$$;

-- copies the syllabus of one session into the next (titles and order, everything pending)
create or replace function public.copy_syllabus(sid uuid, from_session uuid, to_session uuid) returns int
language plpgsql security definer set search_path = public as $$
declare n int;
begin
  if auth.uid() is null or not public.has_perm_school(sid, 'academics.syllabus.create') then raise exception 'not allowed'; end if;
  if from_session = to_session then raise exception 'Choose two different sessions.'; end if;
  if not exists (select 1 from public.sessions where id in (from_session, to_session) and school_id = sid having count(*) = 2) then raise exception 'Session not found.'; end if;
  insert into public.syllabus_units (school_id, session_id, class_id, subject_id, no, title, term)
  select sid, to_session, u.class_id, u.subject_id, u.no, u.title, u.term from public.syllabus_units u
   where u.school_id = sid and u.session_id = from_session
     and not exists (select 1 from public.syllabus_units x where x.session_id = to_session and x.class_id = u.class_id and x.subject_id = u.subject_id and x.title = u.title);
  get diagnostics n = row_count;
  return n;
end $$;

-- ───────────── Audit ─────────────
do $$
declare t text;
begin
  foreach t in array array['class_subjects', 'syllabus_units'] loop
    execute format('drop trigger if exists audit_%1$s on public.%1$I', t);
    execute format('create trigger audit_%1$s after insert or update or delete on public.%1$I for each row execute function public.audit_row()', t);
  end loop;
end $$;

-- ═══════════════════════════════════════════════════════════════════════════
-- Step 24: Payroll v2 — unpaid days from staff attendance (holidays excluded), PF / ESI / professional tax,
--          salary advances with monthly recovery, salary revision history, statutory columns for reports.
-- Safe to run again. Replaces payslip_compute() and generate_payroll() from 0007.
