-- ═══════════════════════════════════════════════════════════════════════════
-- Step 36: Inventory & sales — items with a stock ledger (one source of truth), suppliers and purchases, uniform / book / stationery
--          sales to a student, staff member or walk-in (paid at the counter, or charged to the student's fee account), issue to
--          staff and classes, stock take, low-stock alerts and a dashboard. Money flows into the day book by itself.
-- Safe to run again.
-- ═══════════════════════════════════════════════════════════════════════════

create table if not exists public.inventory_settings (
  school_id        uuid primary key references public.schools(id) on delete cascade,
  sale_prefix      text not null default 'SL' check (length(sale_prefix) between 1 and 8),
  purchase_prefix  text not null default 'PU' check (length(purchase_prefix) between 1 and 8),
  next_sale_no     int not null default 1,
  next_purchase_no int not null default 1,
  post_to_accounts boolean not null default true,
  receipt_footer   text
);

create table if not exists public.inventory_items (
  id            uuid primary key default gen_random_uuid(),
  school_id     uuid not null references public.schools(id) on delete cascade,
  sku           text,
  name          text not null check (length(btrim(name)) between 1 and 120),
  category      text not null default 'General',
  variant       text,                                      -- size / class / colour
  unit          text not null default 'pcs',
  cost          numeric(12,2) not null default 0 check (cost >= 0),
  price         numeric(12,2) not null default 0 check (price >= 0),
  gst_rate      numeric(5,2) not null default 0 check (gst_rate between 0 and 40),
  reorder_level int not null default 0 check (reorder_level >= 0),
  track_stock   boolean not null default true,
  on_hand       int not null default 0,
  for_class_id  uuid references public.classes(id) on delete set null,   -- a book / uniform meant for one class
  location      text,
  barcode       text,
  active        boolean not null default true,
  note          text,
  created_at    timestamptz not null default now(),
  check (not track_stock or on_hand >= 0)
);
create unique index if not exists inventory_items_sku on public.inventory_items (school_id, lower(sku)) where sku is not null;
create index if not exists inventory_items_school on public.inventory_items (school_id, active, category, name);

create table if not exists public.inventory_suppliers (
  id        uuid primary key default gen_random_uuid(),
  school_id uuid not null references public.schools(id) on delete cascade,
  name      text not null check (length(btrim(name)) between 1 and 100),
  phone     text,
  email     text,
  gstin     text,
  address   text,
  active    boolean not null default true,
  created_at timestamptz not null default now(),
  unique (school_id, name)
);

create table if not exists public.inventory_purchases (
  id          uuid primary key default gen_random_uuid(),
  school_id   uuid not null references public.schools(id) on delete cascade,
  no          text not null,
  supplier_id uuid references public.inventory_suppliers(id) on delete set null,
  on_date     date not null default (now() at time zone 'Asia/Kolkata')::date,
  bill_no     text,
  total       numeric(14,2) not null check (total >= 0),
  paid        numeric(14,2) not null default 0 check (paid >= 0),
  mode        text,
  note        text,
  voucher_id  uuid references public.vouchers(id) on delete set null,
  status      text not null default 'posted' check (status in ('posted', 'cancelled')),
  by_name     text,
  created_at  timestamptz not null default now(),
  unique (school_id, no)
);
create table if not exists public.inventory_purchase_lines (
  id          uuid primary key default gen_random_uuid(),
  purchase_id uuid not null references public.inventory_purchases(id) on delete cascade,
  school_id   uuid not null references public.schools(id) on delete cascade,
  item_id     uuid not null references public.inventory_items(id) on delete restrict,
  qty         int not null check (qty > 0),
  unit_cost   numeric(12,2) not null check (unit_cost >= 0),
  line_total  numeric(14,2) not null
);

create table if not exists public.inventory_sales (
  id               uuid primary key default gen_random_uuid(),
  school_id        uuid not null references public.schools(id) on delete cascade,
  no               text not null,
  on_date          date not null default (now() at time zone 'Asia/Kolkata')::date,
  kind             text not null default 'student' check (kind in ('student', 'staff', 'walkin')),
  student_id       uuid references public.students(id) on delete set null,
  staff_id         uuid references public.staff(id) on delete set null,
  customer_name    text,
  phone            text,
  subtotal         numeric(14,2) not null default 0,
  discount         numeric(14,2) not null default 0 check (discount >= 0),
  total            numeric(14,2) not null default 0 check (total >= 0),
  mode             text not null default 'cash' check (mode in ('cash', 'upi', 'card', 'cheque', 'bank_transfer', 'fee_account')),
  status           text not null default 'paid' check (status in ('paid', 'on_fee_account', 'cancelled')),
  fee_due_id       uuid references public.fee_dues(id) on delete set null,
  voucher_id       uuid references public.vouchers(id) on delete set null,
  note             text,
  by_name          text,
  created_at       timestamptz not null default now(),
  cancelled_at     timestamptz,
  cancelled_reason text,
  unique (school_id, no)
);
create index if not exists inventory_sales_day on public.inventory_sales (school_id, on_date desc);
create index if not exists inventory_sales_student on public.inventory_sales (student_id);
create table if not exists public.inventory_sale_lines (
  id         uuid primary key default gen_random_uuid(),
  sale_id    uuid not null references public.inventory_sales(id) on delete cascade,
  school_id  uuid not null references public.schools(id) on delete cascade,
  item_id    uuid not null references public.inventory_items(id) on delete restrict,
  item_name  text not null,
  qty        int not null check (qty > 0),
  unit_price numeric(12,2) not null check (unit_price >= 0),
  line_total numeric(14,2) not null
);

-- every change of stock, signed; items.on_hand is kept equal to the sum by the trigger
create table if not exists public.inventory_moves (
  id         bigint generated always as identity primary key,
  school_id  uuid not null references public.schools(id) on delete cascade,
  item_id    uuid not null references public.inventory_items(id) on delete cascade,
  kind       text not null check (kind in ('opening', 'purchase', 'sale', 'sale_return', 'issue', 'issue_return', 'adjust', 'damage', 'stock_take')),
  qty        int not null check (qty <> 0),
  unit_cost  numeric(12,2),
  ref_type   text,
  ref_id     uuid,
  party      text,                                   -- who it was issued to, or the supplier / customer
  note       text,
  by_name    text,
  created_at timestamptz not null default now()
);
create index if not exists inventory_moves_item on public.inventory_moves (item_id, created_at desc);
create index if not exists inventory_moves_school on public.inventory_moves (school_id, created_at desc);

create or replace function public._inv_apply_move() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  update public.inventory_items set on_hand = on_hand + new.qty where id = new.item_id;
  return new;
end $$;
drop trigger if exists inventory_apply_move on public.inventory_moves;
create trigger inventory_apply_move after insert on public.inventory_moves for each row execute function public._inv_apply_move();

alter table public.inventory_settings enable row level security;
alter table public.inventory_items enable row level security;
alter table public.inventory_suppliers enable row level security;
alter table public.inventory_purchases enable row level security;
alter table public.inventory_purchase_lines enable row level security;
alter table public.inventory_sales enable row level security;
alter table public.inventory_sale_lines enable row level security;
alter table public.inventory_moves enable row level security;

-- reads
do $$
declare r record;
begin
  for r in select * from (values
      ('inventory_items', 'inventory.items.view'), ('inventory_moves', 'inventory.items.view'), ('inventory_suppliers', 'inventory.purchase.view'),
      ('inventory_purchases', 'inventory.purchase.view'), ('inventory_purchase_lines', 'inventory.purchase.view'),
      ('inventory_sales', 'inventory.sales.view'), ('inventory_sale_lines', 'inventory.sales.view')) v(t, p) loop
    execute format('drop policy if exists "read" on public.%I', r.t);
    execute format('create policy "read" on public.%I for select to authenticated using (public.has_perm_school(school_id, %L))', r.t, r.p);
  end loop;
end $$;
-- the sales counter needs to see items and suppliers' names where it sells / buys
drop policy if exists "read" on public.inventory_items;
create policy "read" on public.inventory_items for select to authenticated
  using (public.has_perm_school(school_id, 'inventory.items.view') or public.has_perm_school(school_id, 'inventory.sales.create') or public.has_perm_school(school_id, 'inventory.purchase.create'));
drop policy if exists "read" on public.inventory_settings;
create policy "read" on public.inventory_settings for select to authenticated using (public.has_module_perm(school_id, 'inventory'));
drop policy if exists "write" on public.inventory_settings;
create policy "write" on public.inventory_settings for all to authenticated
  using (public.has_perm_school(school_id, 'inventory.items.edit')) with check (public.has_perm_school(school_id, 'inventory.items.edit'));

-- items and suppliers are edited directly (policies); money and stock only through the functions below
drop policy if exists "create" on public.inventory_items;
create policy "create" on public.inventory_items for insert to authenticated with check (public.has_perm_school(school_id, 'inventory.items.create'));
drop policy if exists "edit" on public.inventory_items;
create policy "edit" on public.inventory_items for update to authenticated using (public.has_perm_school(school_id, 'inventory.items.edit')) with check (public.has_perm_school(school_id, 'inventory.items.edit'));
drop policy if exists "delete" on public.inventory_items;
create policy "delete" on public.inventory_items for delete to authenticated using (public.has_perm_school(school_id, 'inventory.items.delete'));
drop policy if exists "write" on public.inventory_suppliers;
create policy "write" on public.inventory_suppliers for all to authenticated
  using (public.has_perm_school(school_id, 'inventory.purchase.edit')) with check (public.has_perm_school(school_id, 'inventory.purchase.create'));

-- on_hand must not be edited by hand
create or replace function public._inv_guard_item() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then new.on_hand := 0; return new; end if;
  if new.on_hand is distinct from old.on_hand and coalesce(current_setting('app.inv_move', true), '') <> '1' and pg_trigger_depth() < 2 then new.on_hand := old.on_hand; end if;
  return new;
end $$;
drop trigger if exists inventory_guard_item on public.inventory_items;
create trigger inventory_guard_item before insert or update on public.inventory_items for each row execute function public._inv_guard_item();

-- ───────────── helpers ─────────────
create or replace function public._inv_cfg(sid uuid) returns public.inventory_settings
language plpgsql security definer set search_path = public as $$
declare c public.inventory_settings;
begin
  insert into public.inventory_settings (school_id) values (sid) on conflict do nothing;
  select * into c from public.inventory_settings where school_id = sid;
  return c;
end $$;
revoke execute on function public._inv_cfg(uuid) from public, anon, authenticated;

-- one voucher in the day book: kind receipt / payment, under an income / expense head created on first use
create or replace function public._inv_voucher(sid uuid, p_kind text, p_head text, p_amount numeric, p_party text, p_mode text, p_narr text, p_by text, p_date date) returns uuid
language plpgsql security definer set search_path = public as $$
declare head uuid; bk uuid; n int; v uuid; hk text := case when p_kind = 'receipt' then 'income' else 'expense' end;
begin
  perform public._account_defaults(sid);
  select id into head from public.account_heads where school_id = sid and kind = hk and lower(name) = lower(p_head);
  if head is null then insert into public.account_heads (school_id, name, kind) values (sid, p_head, hk) returning id into head; end if;
  select id into bk from public.account_books where school_id = sid and active
   order by (kind = case when p_mode in ('upi', 'card', 'cheque', 'bank_transfer') then 'bank' else 'cash' end) desc, created_at limit 1;
  update public.account_settings set next_no = next_no + 1 where school_id = sid returning next_no - 1 into n;
  insert into public.vouchers (school_id, no, date, kind, head_id, book_id, amount, party, mode, narration, status, created_by_name)
  values (sid, case when p_kind = 'receipt' then 'RV-' else 'PV-' end || lpad(n::text, 5, '0'), p_date, p_kind, head, bk, p_amount, p_party,
          case when p_mode in ('cash', 'upi', 'cheque', 'bank_transfer', 'card') then p_mode else 'cash' end, left(p_narr, 500), 'posted', coalesce(p_by, 'User'))
  returning id into v;
  return v;
end $$;
revoke execute on function public._inv_voucher(uuid, text, text, numeric, text, text, text, text, date) from public, anon, authenticated;

create or replace function public._inv_me(sid uuid) returns text
language sql stable security definer set search_path = public as $$ select coalesce((select name from public.school_members where school_id = sid and user_id = auth.uid()), 'User'); $$;
revoke execute on function public._inv_me(uuid) from public, anon, authenticated;

-- ───────────── stock adjustments ─────────────
-- p_kind: opening (first count), adjust (+/-), damage (written off, always out)
create or replace function public.inventory_adjust(sid uuid, p_item uuid, p_qty int, p_kind text default 'adjust', p_note text default null) returns int
language plpgsql security definer set search_path = public as $$
declare it public.inventory_items; q int := p_qty;
begin
  if auth.uid() is null or not public.has_perm_school(sid, 'inventory.items.edit') then raise exception 'not allowed'; end if;
  if p_kind not in ('opening', 'adjust', 'damage') then raise exception 'Unknown stock change.'; end if;
  if q is null or q = 0 then raise exception 'Enter how many.'; end if;
  if p_kind = 'damage' then q := -abs(q); end if;
  if p_kind = 'opening' and q < 0 then raise exception 'Opening stock cannot be negative.'; end if;
  select * into it from public.inventory_items where id = p_item and school_id = sid for update;
  if it.id is null then raise exception 'Item not found.'; end if;
  if it.track_stock and it.on_hand + q < 0 then raise exception 'Only % in stock — cannot remove %.', it.on_hand, abs(q); end if;
  insert into public.inventory_moves (school_id, item_id, kind, qty, unit_cost, note, by_name) values (sid, p_item, p_kind, q, it.cost, nullif(left(btrim(coalesce(p_note, '')), 200), ''), public._inv_me(sid));
  return it.on_hand + q;
end $$;

-- physical count: [{item, counted}] — the difference becomes one 'stock_take' move per item
create or replace function public.inventory_stock_take(sid uuid, p_counts jsonb) returns int
language plpgsql security definer set search_path = public as $$
declare c jsonb; it public.inventory_items; diff int; n int := 0; me text;
begin
  if auth.uid() is null or not public.has_perm_school(sid, 'inventory.items.edit') then raise exception 'not allowed'; end if;
  me := public._inv_me(sid);
  for c in select * from jsonb_array_elements(coalesce(p_counts, '[]'::jsonb)) loop
    continue when nullif(c ->> 'counted', '') is null;
    select * into it from public.inventory_items where id = (c ->> 'item')::uuid and school_id = sid and track_stock for update;
    continue when it.id is null;
    if (c ->> 'counted')::int < 0 then raise exception 'A count cannot be negative.'; end if;
    diff := (c ->> 'counted')::int - it.on_hand;
    continue when diff = 0;
    insert into public.inventory_moves (school_id, item_id, kind, qty, unit_cost, note, by_name) values (sid, it.id, 'stock_take', diff, it.cost, 'Stock take', me);
    n := n + 1;
  end loop;
  return n;
end $$;

-- ───────────── purchases ─────────────
-- p_lines: [{item, qty, unit_cost}]  — raises stock, updates the item's cost, posts a payment voucher for what was paid
create or replace function public.inventory_purchase(sid uuid, p_supplier uuid, p_date date, p_bill text, p_lines jsonb, p_paid numeric default 0, p_mode text default 'cash', p_note text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare c public.inventory_settings; l jsonb; it public.inventory_items; qty int; uc numeric; tot numeric := 0; pid uuid; no text; me text; sup text; vid uuid; k int := 0; d date := coalesce(p_date, public.today_ist());
begin
  if auth.uid() is null or not public.has_perm_school(sid, 'inventory.purchase.create') then raise exception 'not allowed'; end if;
  if jsonb_array_length(coalesce(p_lines, '[]'::jsonb)) = 0 then raise exception 'Add at least one item.'; end if;
  if d > public.today_ist() then raise exception 'The purchase date cannot be in the future.'; end if;
  if p_supplier is not null then
    select name into sup from public.inventory_suppliers where id = p_supplier and school_id = sid;
    if sup is null then raise exception 'Supplier not found.'; end if;
  end if;
  c := public._inv_cfg(sid);
  me := public._inv_me(sid);
  update public.inventory_settings set next_purchase_no = next_purchase_no + 1 where school_id = sid returning next_purchase_no - 1 into k;
  no := c.purchase_prefix || '-' || lpad(k::text, 4, '0');
  insert into public.inventory_purchases (school_id, no, supplier_id, on_date, bill_no, total, paid, mode, note, by_name)
  values (sid, no, p_supplier, d, nullif(left(btrim(coalesce(p_bill, '')), 40), ''), 0, 0, p_mode, nullif(left(btrim(coalesce(p_note, '')), 200), ''), me) returning id into pid;
  for l in select * from jsonb_array_elements(p_lines) loop
    qty := (l ->> 'qty')::int; uc := coalesce(nullif(l ->> 'unit_cost', '')::numeric, 0);
    if qty is null or qty <= 0 then raise exception 'Quantity must be at least 1.'; end if;
    if uc < 0 then raise exception 'The rate cannot be negative.'; end if;
    select * into it from public.inventory_items where id = (l ->> 'item')::uuid and school_id = sid for update;
    if it.id is null then raise exception 'Item not found.'; end if;
    insert into public.inventory_purchase_lines (purchase_id, school_id, item_id, qty, unit_cost, line_total) values (pid, sid, it.id, qty, uc, round(qty * uc, 2));
    insert into public.inventory_moves (school_id, item_id, kind, qty, unit_cost, ref_type, ref_id, party, by_name) values (sid, it.id, 'purchase', qty, uc, 'purchase', pid, sup, me);
    update public.inventory_items set cost = uc where id = it.id;
    tot := tot + round(qty * uc, 2);
  end loop;
  if coalesce(p_paid, 0) < 0 or coalesce(p_paid, 0) > tot then raise exception 'The amount paid cannot be more than the bill (₹%).', tot; end if;
  if coalesce(p_paid, 0) > 0 and c.post_to_accounts then
    vid := public._inv_voucher(sid, 'payment', 'Inventory purchases', p_paid, coalesce(sup, 'Supplier'), p_mode, 'Purchase ' || no || coalesce(' · bill ' || nullif(btrim(coalesce(p_bill, '')), ''), ''), me, d);
  end if;
  update public.inventory_purchases set total = tot, paid = coalesce(p_paid, 0), voucher_id = vid where id = pid;
  return jsonb_build_object('id', pid, 'no', no, 'total', tot);
end $$;

-- ───────────── sales ─────────────
-- p_lines: [{item, qty, price?}] — a different price needs inventory.sales.edit.  p_mode 'fee_account' bills the student's fee account.
create or replace function public.inventory_sell(sid uuid, p_kind text, p_student uuid, p_staff uuid, p_name text, p_phone text, p_lines jsonb,
                                                 p_discount numeric default 0, p_mode text default 'cash', p_note text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare c public.inventory_settings; l jsonb; it public.inventory_items; qty int; price numeric; sub numeric := 0; tot numeric; sid2 uuid; no text; me text; k int;
        nm text; vid uuid; due uuid; head uuid; sess uuid; st text; can_price boolean; ids uuid[] := '{}'; d date := public.today_ist(); disc numeric := greatest(coalesce(p_discount, 0), 0);
begin
  if auth.uid() is null or not public.has_perm_school(sid, 'inventory.sales.create') then raise exception 'not allowed'; end if;
  if p_kind not in ('student', 'staff', 'walkin') then raise exception 'Choose who is buying.'; end if;
  if p_mode not in ('cash', 'upi', 'card', 'cheque', 'bank_transfer', 'fee_account') then raise exception 'Choose how it is paid.'; end if;
  if jsonb_array_length(coalesce(p_lines, '[]'::jsonb)) = 0 then raise exception 'Add at least one item.'; end if;
  if p_kind = 'student' then
    select btrim(concat_ws(' ', first_name, last_name)), status into nm, st from public.students where id = p_student and school_id = sid;
    if nm is null then raise exception 'Choose the student.'; end if;
    if st not in ('active', 'admission_pending') then raise exception 'This student is no longer on roll.'; end if;
  elsif p_kind = 'staff' then
    select name into nm from public.staff where id = p_staff and school_id = sid;
    if nm is null then raise exception 'Choose the staff member.'; end if;
    if p_mode = 'fee_account' then raise exception 'Only a student can be charged to the fee account.'; end if;
  else
    nm := nullif(btrim(coalesce(p_name, '')), '');
    if p_mode = 'fee_account' then raise exception 'Only a student can be charged to the fee account.'; end if;
  end if;
  if p_mode = 'fee_account' and p_kind <> 'student' then raise exception 'Only a student can be charged to the fee account.'; end if;
  can_price := public.has_perm_school(sid, 'inventory.sales.edit');
  c := public._inv_cfg(sid);
  me := public._inv_me(sid);
  update public.inventory_settings set next_sale_no = next_sale_no + 1 where school_id = sid returning next_sale_no - 1 into k;
  no := c.sale_prefix || '-' || lpad(k::text, 5, '0');
  insert into public.inventory_sales (school_id, no, on_date, kind, student_id, staff_id, customer_name, phone, mode, status, note, by_name)
  values (sid, no, d, p_kind, case when p_kind = 'student' then p_student end, case when p_kind = 'staff' then p_staff end, nm, nullif(btrim(coalesce(p_phone, '')), ''), p_mode,
          case when p_mode = 'fee_account' then 'on_fee_account' else 'paid' end, nullif(left(btrim(coalesce(p_note, '')), 200), ''), me) returning id into sid2;
  -- lock the items in a fixed order so two counters never deadlock
  for l in select x from jsonb_array_elements(p_lines) x order by (x ->> 'item') loop
    qty := (l ->> 'qty')::int;
    if qty is null or qty <= 0 then raise exception 'Quantity must be at least 1.'; end if;
    select * into it from public.inventory_items where id = (l ->> 'item')::uuid and school_id = sid for update;
    if it.id is null or not it.active then raise exception 'An item is missing or withdrawn.'; end if;
    if (l ->> 'item')::uuid = any(ids) then raise exception '“%” is listed twice — combine the quantity.', it.name; end if;
    ids := ids || it.id;
    if it.track_stock and it.on_hand < qty then raise exception 'Only % of “%” in stock.', it.on_hand, it.name; end if;
    price := case when can_price and nullif(l ->> 'price', '') is not null then (l ->> 'price')::numeric else it.price end;
    if price < 0 then raise exception 'The price cannot be negative.'; end if;
    insert into public.inventory_sale_lines (sale_id, school_id, item_id, item_name, qty, unit_price, line_total)
    values (sid2, sid, it.id, it.name || coalesce(' (' || it.variant || ')', ''), qty, price, round(qty * price, 2));
    if it.track_stock then
      insert into public.inventory_moves (school_id, item_id, kind, qty, unit_cost, ref_type, ref_id, party, by_name) values (sid, it.id, 'sale', -qty, it.cost, 'sale', sid2, nm, me);
    end if;
    sub := sub + round(qty * price, 2);
  end loop;
  if disc > sub then raise exception 'The discount is more than the bill.'; end if;
  if disc > 0 and not can_price then raise exception 'A discount needs the sales-edit permission.'; end if;
  tot := sub - disc;
  if p_mode = 'fee_account' then
    select id into sess from public.sessions where school_id = sid and is_current;
    if sess is null then raise exception 'There is no current session to bill the student in.'; end if;
    select id into head from public.fee_heads where school_id = sid and name = 'Uniform & Books';
    if head is null then insert into public.fee_heads (school_id, name, sort) values (sid, 'Uniform & Books', 70) returning id into head; end if;
    insert into public.fee_dues (school_id, session_id, student_id, fee_head_id, label, due_date, amount, concession, source_key)
    values (sid, sess, p_student, head, 'Uniform & Books · ' || no, d, tot, 0, 'sale:' || sid2) returning id into due;
  elsif tot > 0 and c.post_to_accounts then
    vid := public._inv_voucher(sid, 'receipt', 'Sale of books & uniform', tot, coalesce(nm, 'Walk-in customer'), p_mode, 'Sale ' || no, me, d);
  end if;
  update public.inventory_sales set subtotal = sub, discount = disc, total = tot, fee_due_id = due, voucher_id = vid where id = sid2;
  return jsonb_build_object('id', sid2, 'no', no, 'total', tot, 'on_fee_account', p_mode = 'fee_account');
end $$;

-- cancel a sale: stock goes back, the voucher is cancelled, an unpaid fee-account charge is removed
create or replace function public.inventory_cancel_sale(sid uuid, p_sale uuid, p_reason text) returns void
language plpgsql security definer set search_path = public as $$
declare s public.inventory_sales; l record; d public.fee_dues;
begin
  if auth.uid() is null or not public.has_perm_school(sid, 'inventory.sales.edit') then raise exception 'not allowed'; end if;
  select * into s from public.inventory_sales where id = p_sale and school_id = sid for update;
  if s.id is null then raise exception 'Sale not found.'; end if;
  if s.status = 'cancelled' then raise exception 'This sale is already cancelled.'; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'Give a reason for cancelling.'; end if;
  if s.fee_due_id is not null then
    select * into d from public.fee_dues where id = s.fee_due_id;
    if d.id is not null and d.paid > 0 then raise exception 'The parent has already paid ₹% of this charge — refund it from Fees first.', d.paid; end if;
    delete from public.fee_dues where id = s.fee_due_id;
  end if;
  for l in select sl.item_id, sl.qty from public.inventory_sale_lines sl join public.inventory_items i on i.id = sl.item_id where sl.sale_id = p_sale and i.track_stock loop
    insert into public.inventory_moves (school_id, item_id, kind, qty, ref_type, ref_id, note, by_name) values (sid, l.item_id, 'sale_return', l.qty, 'sale', p_sale, 'Sale ' || s.no || ' cancelled', public._inv_me(sid));
  end loop;
  if s.voucher_id is not null then
    update public.vouchers set status = 'cancelled', decided_by_name = public._inv_me(sid), decided_at = now(), decision_note = 'Sale ' || s.no || ' cancelled' where id = s.voucher_id and status = 'posted';
  end if;
  update public.inventory_sales set status = 'cancelled', cancelled_at = now(), cancelled_reason = left(btrim(p_reason), 300), fee_due_id = null where id = p_sale;
end $$;

-- ───────────── issue to staff / class (no money) ─────────────
create or replace function public.inventory_issue(sid uuid, p_item uuid, p_qty int, p_to text, p_note text default null, p_return boolean default false) returns int
language plpgsql security definer set search_path = public as $$
declare it public.inventory_items; q int := p_qty;
begin
  if auth.uid() is null or not public.has_perm_school(sid, 'inventory.items.edit') then raise exception 'not allowed'; end if;
  if q is null or q <= 0 then raise exception 'Enter how many.'; end if;
  if coalesce(btrim(p_to), '') = '' then raise exception 'Write who it is for (a teacher, a class, a department).'; end if;
  select * into it from public.inventory_items where id = p_item and school_id = sid for update;
  if it.id is null then raise exception 'Item not found.'; end if;
  if not p_return and it.track_stock and it.on_hand < q then raise exception 'Only % in stock.', it.on_hand; end if;
  insert into public.inventory_moves (school_id, item_id, kind, qty, unit_cost, party, note, by_name)
  values (sid, p_item, case when p_return then 'issue_return' else 'issue' end, case when p_return then q else -q end, it.cost, left(btrim(p_to), 80), nullif(left(btrim(coalesce(p_note, '')), 200), ''), public._inv_me(sid));
  return it.on_hand + case when p_return then q else -q end;
end $$;

-- ───────────── lists and dashboard ─────────────
create or replace function public.inventory_item_list(sid uuid, p_q text default null, p_category text default null, p_state text default null, p_active text default 'yes',
                                                      p_limit int default 25, p_offset int default 0)
returns table (id uuid, sku text, name text, category text, variant text, unit text, cost numeric, price numeric, reorder_level int, track_stock boolean, on_hand int,
               stock_value numeric, active boolean, class_name text, location text, sold_30 bigint, state text, total bigint)
language sql stable security definer set search_path = public as $$
  select i.id, i.sku, i.name, i.category, i.variant, i.unit, i.cost, i.price, i.reorder_level, i.track_stock, i.on_hand, round(i.on_hand * i.cost, 2), i.active, c.name, i.location,
         coalesce((select sum(-m.qty) from public.inventory_moves m where m.item_id = i.id and m.kind = 'sale' and m.created_at >= now() - interval '30 days'), 0)::bigint,
         case when not i.track_stock then 'na' when i.on_hand <= 0 then 'out' when i.on_hand <= i.reorder_level then 'low' else 'ok' end, count(*) over ()
    from public.inventory_items i left join public.classes c on c.id = i.for_class_id
   where i.school_id = sid and (public.has_perm_school(sid, 'inventory.items.view') or public.has_perm_school(sid, 'inventory.sales.create') or public.has_perm_school(sid, 'inventory.purchase.create'))
     and (p_active is null or p_active = 'all' or (p_active = 'yes' and i.active) or (p_active = 'no' and not i.active))
     and (p_category is null or i.category = p_category)
     and (p_state is null or (p_state = 'out' and i.track_stock and i.on_hand <= 0) or (p_state = 'low' and i.track_stock and i.on_hand > 0 and i.on_hand <= i.reorder_level)
          or (p_state = 'attention' and i.track_stock and i.on_hand <= i.reorder_level) or (p_state = 'ok' and (not i.track_stock or i.on_hand > i.reorder_level)))
     and (nullif(btrim(coalesce(p_q, '')), '') is null or concat_ws(' ', i.name, i.sku, i.category, i.variant, i.barcode) ilike public.like_escape(btrim(p_q)))
   order by i.category, i.name, i.variant
   limit least(greatest(coalesce(p_limit, 25), 1), 200) offset greatest(coalesce(p_offset, 0), 0);
$$;

create or replace function public.inventory_sale_list(sid uuid, p_q text default null, p_from date default null, p_to date default null, p_status text default null, p_kind text default null,
                                                      p_limit int default 25, p_offset int default 0)
returns table (id uuid, no text, on_date date, kind text, customer_name text, student_id uuid, admission_no text, class_name text, total numeric, mode text, status text, items text,
               fee_paid numeric, by_name text, cancelled_reason text, total_rows bigint)
language sql stable security definer set search_path = public as $$
  select s.id, s.no, s.on_date, s.kind, coalesce(btrim(concat_ws(' ', st.first_name, st.last_name)), w.name, s.customer_name), s.student_id, st.admission_no, c.name, s.total, s.mode, s.status,
         (select string_agg(l.item_name || ' ×' || l.qty, ', ' order by l.item_name) from public.inventory_sale_lines l where l.sale_id = s.id),
         case when d.id is not null then d.paid end, s.by_name, s.cancelled_reason, count(*) over ()
    from public.inventory_sales s
    left join public.students st on st.id = s.student_id
    left join public.classes c on c.id = st.class_id
    left join public.staff w on w.id = s.staff_id
    left join public.fee_dues d on d.id = s.fee_due_id
   where s.school_id = sid and public.has_perm_school(sid, 'inventory.sales.view')
     and (p_from is null or s.on_date >= p_from) and (p_to is null or s.on_date <= p_to) and (p_status is null or s.status = p_status) and (p_kind is null or s.kind = p_kind)
     and (nullif(btrim(coalesce(p_q, '')), '') is null or concat_ws(' ', s.no, s.customer_name, st.first_name, st.last_name, st.admission_no, w.name, s.phone) ilike public.like_escape(btrim(p_q)))
   order by s.created_at desc
   limit least(greatest(coalesce(p_limit, 25), 1), 200) offset greatest(coalesce(p_offset, 0), 0);
$$;

create or replace function public.inventory_move_list(sid uuid, p_item uuid default null, p_kind text default null, p_from date default null, p_to date default null,
                                                      p_limit int default 25, p_offset int default 0)
returns table (id bigint, created_at timestamptz, item_id uuid, item_name text, kind text, qty int, unit_cost numeric, party text, note text, by_name text, total bigint)
language sql stable security definer set search_path = public as $$
  select m.id, m.created_at, i.id, i.name || coalesce(' (' || i.variant || ')', ''), m.kind, m.qty, m.unit_cost, m.party, m.note, m.by_name, count(*) over ()
    from public.inventory_moves m join public.inventory_items i on i.id = m.item_id
   where m.school_id = sid and public.has_perm_school(sid, 'inventory.items.view')
     and (p_item is null or m.item_id = p_item) and (p_kind is null or m.kind = p_kind)
     and (p_from is null or (m.created_at at time zone 'Asia/Kolkata')::date >= p_from) and (p_to is null or (m.created_at at time zone 'Asia/Kolkata')::date <= p_to)
   order by m.created_at desc, m.id desc
   limit least(greatest(coalesce(p_limit, 25), 1), 200) offset greatest(coalesce(p_offset, 0), 0);
$$;

create or replace function public.inventory_dashboard(sid uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare d date := public.today_ist();
begin
  if not (public.has_perm_school(sid, 'inventory.items.view') or public.has_perm_school(sid, 'inventory.sales.view') or public.has_perm_school(sid, 'inventory.purchase.view')) then raise exception 'not allowed'; end if;
  return jsonb_build_object(
    'items', (select count(*) from public.inventory_items where school_id = sid and active),
    'units', (select coalesce(sum(on_hand), 0) from public.inventory_items where school_id = sid and active and track_stock),
    'stock_value', (select coalesce(sum(on_hand * cost), 0) from public.inventory_items where school_id = sid and active and track_stock),
    'low', (select count(*) from public.inventory_items where school_id = sid and active and track_stock and on_hand > 0 and on_hand <= reorder_level),
    'out', (select count(*) from public.inventory_items where school_id = sid and active and track_stock and on_hand <= 0),
    'sales_today', (select coalesce(sum(total), 0) from public.inventory_sales where school_id = sid and on_date = d and status <> 'cancelled'),
    'sales_month', (select coalesce(sum(total), 0) from public.inventory_sales where school_id = sid and on_date >= date_trunc('month', d)::date and status <> 'cancelled'),
    'bills_month', (select count(*) from public.inventory_sales where school_id = sid and on_date >= date_trunc('month', d)::date and status <> 'cancelled'),
    'on_fee_account', (select coalesce(sum(greatest(f.amount - f.concession + f.fine - f.paid, 0)), 0) from public.inventory_sales s join public.fee_dues f on f.id = s.fee_due_id where s.school_id = sid and s.status = 'on_fee_account'),
    'purchases_month', (select coalesce(sum(total), 0) from public.inventory_purchases where school_id = sid and on_date >= date_trunc('month', d)::date and status <> 'cancelled'),
    'per_month', coalesce((select jsonb_agg(jsonb_build_object('m', to_char(m, 'Mon'), 'sales', s, 'purchases', p) order by m) from (
        select g::date m,
               (select coalesce(sum(total), 0) from public.inventory_sales x where x.school_id = sid and x.status <> 'cancelled' and date_trunc('month', x.on_date) = g) s,
               (select coalesce(sum(total), 0) from public.inventory_purchases x where x.school_id = sid and x.status <> 'cancelled' and date_trunc('month', x.on_date) = g) p
          from generate_series(date_trunc('month', d) - interval '5 months', date_trunc('month', d), interval '1 month') g) q), '[]'::jsonb),
    'top_items', coalesce((select jsonb_agg(jsonb_build_object('name', name, 'qty', q, 'amount', a)) from (
        select l.item_name name, sum(l.qty) q, sum(l.line_total) a from public.inventory_sale_lines l join public.inventory_sales s on s.id = l.sale_id
         where s.school_id = sid and s.status <> 'cancelled' and s.on_date >= d - 90 group by l.item_name order by sum(l.line_total) desc limit 6) x), '[]'::jsonb),
    'reorder', coalesce((select jsonb_agg(jsonb_build_object('id', id, 'name', name || coalesce(' (' || variant || ')', ''), 'on_hand', on_hand, 'reorder', reorder_level) order by on_hand) from (
        select id, name, variant, on_hand, reorder_level from public.inventory_items where school_id = sid and active and track_stock and on_hand <= reorder_level order by on_hand limit 8) x), '[]'::jsonb));
end $$;

do $$
declare t text;
begin
  foreach t in array array['inventory_items', 'inventory_suppliers', 'inventory_purchases', 'inventory_sales', 'inventory_settings'] loop
    execute format('drop trigger if exists audit_%1$s on public.%1$I', t);
    execute format('create trigger audit_%1$s after insert or update or delete on public.%1$I for each row execute function public.audit_row()', t);
  end loop;
end $$;

notify pgrst, 'reload schema';

-- ═══════════════════════════════════════════════════════════════════════════
-- Step 37: one money trail per student — whatever a module charges a student (UP Board registration fee, library fine,
--          discipline fine, uniform & book bills, damaged / lost property, hostel, transport …) becomes a due on the student's
--          FEE ACCOUNT, collected at the one fee counter and shown in the one ledger. Payment status flows back to the module.
-- Safe to run again.
-- ═══════════════════════════════════════════════════════════════════════════

-- ───────────── the internal helper every module uses ─────────────
-- Creates (or updates, while still unpaid) one due for a student. The source key makes it idempotent: the same event never bills twice.
create or replace function public.charge_student(sid uuid, p_student uuid, p_head text, p_label text, p_amount numeric, p_due date, p_key text) returns uuid
language plpgsql security definer set search_path = public as $$
declare head uuid; sess uuid; ex public.fee_dues; nid uuid;
begin
  if p_amount is null or p_amount <= 0 then return null; end if;
  select id into ex.id from public.fee_dues where student_id = p_student and source_key = p_key;
  if ex.id is not null then
    update public.fee_dues set amount = p_amount, label = left(p_label, 120) where id = ex.id and paid = 0 and amount is distinct from p_amount;
    return ex.id;
  end if;
  select id into sess from public.sessions where school_id = sid and is_current;
  if sess is null then select id into sess from public.sessions where school_id = sid order by start_date desc limit 1; end if;
  if sess is null then raise exception 'The school has no session to bill the student in.'; end if;
  select id into head from public.fee_heads where school_id = sid and lower(name) = lower(p_head);
  if head is null then insert into public.fee_heads (school_id, name, sort) values (sid, p_head, 90) returning id into head; end if;
  insert into public.fee_dues (school_id, session_id, student_id, fee_head_id, label, due_date, amount, concession, source_key)
  values (sid, sess, p_student, head, left(p_label, 120), coalesce(p_due, public.today_ist()), round(p_amount, 2), 0, p_key) returning id into nid;
  return nid;
end $$;
revoke execute on function public.charge_student(uuid, uuid, text, text, numeric, date, text) from public, anon, authenticated;

-- removes an UNPAID charge again (the event was cancelled); a partly paid one is left for a refund
create or replace function public.uncharge_student(p_student uuid, p_key text) returns boolean
language plpgsql security definer set search_path = public as $$
begin
  delete from public.fee_dues where student_id = p_student and source_key = p_key and paid = 0;
  return found;
end $$;
revoke execute on function public.uncharge_student(uuid, text) from public, anon, authenticated;

-- ───────────── UP Board registration fee → fee account ─────────────
create or replace function public.board_fee_to_account() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.fee_total > 0 then
    perform public.charge_student(new.school_id, new.student_id, 'Board Registration Fee',
      case new.kind when 'advance_registration' then 'UP Board registration fee' else 'UP Board exam form fee' end || ' · Class ' || new.class_level,
      new.fee_total, public.today_ist(), 'board:' || new.id);
  else
    perform public.uncharge_student(new.student_id, 'board:' || new.id);
  end if;
  return new;
end $$;
drop trigger if exists board_fee_to_account on public.board_registrations;
create trigger board_fee_to_account after insert or update of fee_total on public.board_registrations
  for each row execute function public.board_fee_to_account();

-- existing registrations get their charge once
insert into public.fee_heads (school_id, name, sort)
select distinct b.school_id, 'Board Registration Fee', 90 from public.board_registrations b
 where b.fee_total > 0 and not exists (select 1 from public.fee_heads h where h.school_id = b.school_id and lower(h.name) = 'board registration fee');
do $$
declare r record;
begin
  for r in select * from public.board_registrations where fee_total > 0 loop
    perform public.charge_student(r.school_id, r.student_id, 'Board Registration Fee',
      case r.kind when 'advance_registration' then 'UP Board registration fee' else 'UP Board exam form fee' end || ' · Class ' || r.class_level,
      r.fee_total, public.today_ist(), 'board:' || r.id);
  end loop;
end $$;

-- ───────────── library fine → fee account (students) ─────────────
alter table public.library_issues add column if not exists fine_due_id uuid references public.fee_dues(id) on delete set null;

create or replace function public.library_fine_to_account() returns trigger
language plpgsql security definer set search_path = public as $$
declare did uuid; t text;
begin
  if new.returned_on is not null and coalesce(new.fine, 0) > 0 and not coalesce(new.fine_waived, false) and new.student_id is not null and new.fine_due_id is null and new.fine_paid_on is null then
    select title into t from public.library_books where id = new.book_id;
    did := public.charge_student(new.school_id, new.student_id, 'Library Fine', 'Library fine · ' || coalesce(t, 'book') || case when new.lost then ' (lost)' else '' end,
                                 new.fine, public.today_ist(), 'libfine:' || new.id);
    if did is not null then update public.library_issues set fine_due_id = did where id = new.id; end if;
  end if;
  return new;
end $$;
drop trigger if exists library_fine_to_account on public.library_issues;
create trigger library_fine_to_account after update of returned_on, fine on public.library_issues
  for each row execute function public.library_fine_to_account();

-- unpaid student fines from before this step move to the fee account once
do $$
declare r record; did uuid;
begin
  for r in select i.id, i.school_id, i.student_id, i.fine, i.lost, b.title from public.library_issues i join public.library_books b on b.id = i.book_id
            where i.returned_on is not null and i.fine > 0 and i.fine_paid_on is null and not i.fine_waived and i.student_id is not null and i.fine_due_id is null loop
    did := public.charge_student(r.school_id, r.student_id, 'Library Fine', 'Library fine · ' || r.title || case when r.lost then ' (lost)' else '' end, r.fine, public.today_ist(), 'libfine:' || r.id);
    update public.library_issues set fine_due_id = did where id = r.id;
  end loop;
end $$;

-- a fine already on the fee account is collected there, not twice
create or replace function public.library_collect_fine(sid uuid, p_issue uuid, p_mode text default 'cash') returns void
language plpgsql security definer set search_path = public as $$
declare it public.library_issues; head uuid; bk uuid; n int; me text; nm text; ttl text;
begin
  if auth.uid() is null or not public.has_perm_school(sid, 'library.circulation.edit') then raise exception 'not allowed'; end if;
  select * into it from public.library_issues where id = p_issue and school_id = sid;
  if it.id is null or it.returned_on is null then raise exception 'Return the book first.'; end if;
  if it.fine <= 0 or it.fine_paid_on is not null then raise exception 'There is no fine to collect.'; end if;
  if it.fine_due_id is not null then raise exception 'This fine is on the student''s fee account — collect it at the fee counter.'; end if;
  perform public._account_defaults(sid);
  select id into head from public.account_heads where school_id = sid and kind = 'income' and lower(name) = 'library fines';
  if head is null then insert into public.account_heads (school_id, name, kind) values (sid, 'Library fines', 'income') returning id into head; end if;
  select id into bk from public.account_books where school_id = sid and active order by (kind = 'cash') desc, created_at limit 1;
  update public.account_settings set next_no = next_no + 1 where school_id = sid returning next_no - 1 into n;
  select name into me from public.school_members where school_id = sid and user_id = auth.uid();
  select coalesce((select btrim(concat_ws(' ', first_name, last_name)) from public.students where id = it.student_id), (select name from public.staff where id = it.staff_id)) into nm;
  select title into ttl from public.library_books where id = it.book_id;
  insert into public.vouchers (school_id, no, date, kind, head_id, book_id, amount, party, mode, narration, status, created_by_name)
  values (sid, 'RV-' || lpad(n::text, 5, '0'), public.today_ist(), 'receipt', head, bk, it.fine, nm, case when p_mode in ('cash', 'upi', 'cheque', 'bank_transfer', 'card') then p_mode else 'cash' end,
          left('Library fine — ' || ttl, 500), 'posted', coalesce(me, 'User'));
  update public.library_issues set fine_paid_on = public.today_ist() where id = p_issue;
end $$;

-- ───────────── discipline fine → fee account ─────────────
alter table public.discipline_incidents add column if not exists fine_amount numeric(10,2) not null default 0 check (fine_amount >= 0);

create or replace function public.discipline_set_fine(sid uuid, p_incident uuid, p_amount numeric) returns int
language plpgsql security definer set search_path = public as $$
declare i public.discipline_incidents; r record; n int := 0; amt numeric := coalesce(p_amount, 0);
begin
  select * into i from public.discipline_incidents where id = p_incident and school_id = sid;
  if i.id is null or auth.uid() is null or not public.has_perm_school(sid, 'wellbeing.discipline.approve') then raise exception 'not allowed'; end if;
  if amt < 0 or amt > 100000 then raise exception 'The fine must be between ₹0 and ₹1,00,000.'; end if;
  update public.discipline_incidents set fine_amount = amt where id = p_incident;
  for r in select ds.student_id from public.discipline_students ds where ds.incident_id = p_incident and ds.role = 'involved' loop
    if amt > 0 then
      perform public.charge_student(sid, r.student_id, 'Discipline Fine', 'Discipline fine · ' || replace(i.category, '_', ' ') || ' · ' || to_char(i.incident_on, 'DD Mon'), amt, public.today_ist(), 'disc:' || p_incident || ':' || r.student_id);
      n := n + 1;
    else
      perform public.uncharge_student(r.student_id, 'disc:' || p_incident || ':' || r.student_id);
    end if;
  end loop;
  return n;
end $$;

-- ───────────── payment status flows back to the module that raised the charge ─────────────
create or replace function public.charge_paid_sync() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.source_key is null or new.paid < new.amount - new.concession + new.fine or new.paid is not distinct from old.paid then return new; end if;
  if new.source_key like 'board:%' then
    update public.board_registrations set fee_paid_on = coalesce(fee_paid_on, public.today_ist()) where id = nullif(substr(new.source_key, 7), '')::uuid and fee_paid_on is null;
  elsif new.source_key like 'libfine:%' then
    update public.library_issues set fine_paid_on = coalesce(fine_paid_on, public.today_ist()) where id = nullif(substr(new.source_key, 9), '')::uuid and fine_paid_on is null;
  end if;
  return new;
end $$;
drop trigger if exists charge_paid_sync on public.fee_dues;
create trigger charge_paid_sync after update of paid on public.fee_dues for each row execute function public.charge_paid_sync();

-- a student's charges that came from other modules (profile card)
create or replace function public.student_charges(sid uuid, p_student uuid)
returns table (id uuid, head text, label text, amount numeric, paid numeric, balance numeric, due_date date, source text)
language sql stable security definer set search_path = public as $$
  select d.id, h.name, d.label, d.amount - d.concession + d.fine, d.paid, greatest(d.amount - d.concession + d.fine - d.paid, 0), d.due_date,
         split_part(d.source_key, ':', 1)
    from public.fee_dues d left join public.fee_heads h on h.id = d.fee_head_id
   where d.school_id = sid and d.student_id = p_student and d.source_key is not null and d.source_key not like 'dues:%'
     and (public.can_student(sid, 'fees.collection.view', p_student) or public.can_student(sid, 'students.profile.view', p_student))
   order by d.due_date desc;
$$;

notify pgrst, 'reload schema';

-- ═══════════════════════════════════════════════════════════════════════════
-- Step 38: Inventory = the school's property. Fans, benches, computers, lab kits, sports goods … with their stock in the store,
--          where each one is (classroom, lab, office), who holds it (a staff member, a student, a department), return dates,
--          condition, repairs, write-offs and recovery of damaged / lost property from the student's fee account.
--          (The uniform & book shop of step 36 stays as "shop" items.)  Also: TC clearance — no transfer certificate
--          until the student's fees are paid in full.
-- Safe to run again.
-- ═══════════════════════════════════════════════════════════════════════════

-- ───────────── item kinds ─────────────
do $$
begin
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'inventory_items' and column_name = 'kind') then
    alter table public.inventory_items add column kind text not null default 'asset' check (kind in ('asset', 'consumable', 'shop'));
    update public.inventory_items set kind = 'shop' where category in ('Uniform', 'Books', 'Stationery');
  end if;
end $$;
alter table public.inventory_items add column if not exists warranty_until date;
alter table public.inventory_items add column if not exists supplier_id uuid references public.inventory_suppliers(id) on delete set null;

alter table public.inventory_moves drop constraint if exists inventory_moves_kind_check;
alter table public.inventory_moves add constraint inventory_moves_kind_check
  check (kind in ('opening', 'purchase', 'sale', 'sale_return', 'issue', 'issue_return', 'adjust', 'damage', 'stock_take', 'assign', 'return', 'writeoff'));

-- ───────────── places ─────────────
create table if not exists public.inventory_locations (
  id          uuid primary key default gen_random_uuid(),
  school_id   uuid not null references public.schools(id) on delete cascade,
  name        text not null check (length(btrim(name)) between 1 and 60),
  kind        text not null default 'classroom' check (kind in ('classroom', 'lab', 'office', 'library', 'hostel', 'staffroom', 'ground', 'store', 'other')),
  class_id    uuid references public.classes(id) on delete set null,
  section_id  uuid references public.sections(id) on delete set null,
  building    text,
  in_charge_staff_id uuid references public.staff(id) on delete set null,
  active      boolean not null default true,
  created_at  timestamptz not null default now(),
  unique (school_id, name)
);

-- ───────────── who holds what ─────────────
create table if not exists public.inventory_assignments (
  id               uuid primary key default gen_random_uuid(),
  school_id        uuid not null references public.schools(id) on delete cascade,
  item_id          uuid not null references public.inventory_items(id) on delete restrict,
  qty              int not null check (qty > 0),
  holder_kind      text not null check (holder_kind in ('location', 'staff', 'student', 'department')),
  location_id      uuid references public.inventory_locations(id) on delete restrict,
  staff_id         uuid references public.staff(id) on delete restrict,
  student_id       uuid references public.students(id) on delete restrict,
  department       text,
  tag              text,                              -- serial / asset tag of the unit(s)
  assigned_on      date not null default (now() at time zone 'Asia/Kolkata')::date,
  due_back         date,
  note             text,
  status           text not null default 'active' check (status in ('active', 'returned', 'damaged', 'lost', 'repair')),
  returned_on      date,
  return_condition text check (return_condition in ('good', 'needs_repair', 'damaged', 'lost')),
  return_note      text,
  assigned_by_name text,
  returned_by_name text,
  charge_due_id    uuid references public.fee_dues(id) on delete set null,
  created_at       timestamptz not null default now(),
  check ((holder_kind = 'location' and location_id is not null) or (holder_kind = 'staff' and staff_id is not null) or (holder_kind = 'student' and student_id is not null)
         or (holder_kind = 'department' and coalesce(btrim(department), '') <> ''))
);
create index if not exists inventory_assign_school on public.inventory_assignments (school_id, status, created_at desc);
create index if not exists inventory_assign_item on public.inventory_assignments (item_id, status);
create index if not exists inventory_assign_staff on public.inventory_assignments (staff_id) where staff_id is not null;
create index if not exists inventory_assign_student on public.inventory_assignments (student_id) where student_id is not null;
create index if not exists inventory_assign_location on public.inventory_assignments (location_id) where location_id is not null;

create table if not exists public.inventory_assignment_events (
  id            bigint generated always as identity primary key,
  school_id     uuid not null references public.schools(id) on delete cascade,
  assignment_id uuid not null references public.inventory_assignments(id) on delete cascade,
  at            timestamptz not null default now(),
  by_name       text,
  action        text not null,
  detail        text
);
create index if not exists inventory_assign_events on public.inventory_assignment_events (assignment_id, at);

create table if not exists public.inventory_repairs (
  id            uuid primary key default gen_random_uuid(),
  school_id     uuid not null references public.schools(id) on delete cascade,
  item_id       uuid not null references public.inventory_items(id) on delete restrict,
  qty           int not null default 1 check (qty > 0),
  assignment_id uuid references public.inventory_assignments(id) on delete set null,
  location_id   uuid references public.inventory_locations(id) on delete set null,
  issue         text not null check (length(btrim(issue)) > 0),
  removed       boolean not null default false,     -- true: the units came back from their place and are out of the store until fixed
  reported_on   date not null default (now() at time zone 'Asia/Kolkata')::date,
  status        text not null default 'open' check (status in ('open', 'fixed', 'written_off')),
  cost          numeric(12,2) check (cost is null or cost >= 0),
  vendor        text,
  closed_on     date,
  result_note   text,
  by_name       text,
  closed_by_name text,
  created_at    timestamptz not null default now()
);
create index if not exists inventory_repairs_idx on public.inventory_repairs (school_id, status, reported_on desc);

alter table public.inventory_locations enable row level security;
alter table public.inventory_assignments enable row level security;
alter table public.inventory_assignment_events enable row level security;
alter table public.inventory_repairs enable row level security;

drop policy if exists "read" on public.inventory_locations;
create policy "read" on public.inventory_locations for select to authenticated
  using (public.has_perm_school(school_id, 'inventory.items.view') or public.has_perm_school(school_id, 'inventory.assign.view'));
drop policy if exists "write" on public.inventory_locations;
create policy "write" on public.inventory_locations for all to authenticated
  using (public.has_perm_school(school_id, 'inventory.items.edit')) with check (public.has_perm_school(school_id, 'inventory.items.create'));
drop policy if exists "read" on public.inventory_assignments;
create policy "read" on public.inventory_assignments for select to authenticated
  using (public.has_perm_school(school_id, 'inventory.assign.view') or public.has_perm_school(school_id, 'inventory.items.view'));
drop policy if exists "read" on public.inventory_assignment_events;
create policy "read" on public.inventory_assignment_events for select to authenticated
  using (public.has_perm_school(school_id, 'inventory.assign.view') or public.has_perm_school(school_id, 'inventory.items.view'));
drop policy if exists "read" on public.inventory_repairs;
create policy "read" on public.inventory_repairs for select to authenticated
  using (public.has_perm_school(school_id, 'inventory.assign.view') or public.has_perm_school(school_id, 'inventory.items.view'));
-- assignments, repairs and their history are written by the functions below

-- ───────────── helpers ─────────────
create or replace function public._inv_holder(sid uuid, a public.inventory_assignments) returns text
language sql stable security definer set search_path = public as $$
  select case a.holder_kind
    when 'location' then (select name from public.inventory_locations where id = a.location_id)
    when 'staff' then (select name from public.staff where id = a.staff_id)
    when 'student' then (select btrim(concat_ws(' ', first_name, last_name)) from public.students where id = a.student_id)
    else a.department end;
$$;
revoke execute on function public._inv_holder(uuid, public.inventory_assignments) from public, anon, authenticated;

create or replace function public._inv_event(sid uuid, a uuid, p_action text, p_detail text) returns void
language sql security definer set search_path = public as $$
  insert into public.inventory_assignment_events (school_id, assignment_id, by_name, action, detail) values (sid, a, public._inv_me(sid), p_action, left(p_detail, 300));
$$;
revoke execute on function public._inv_event(uuid, uuid, text, text) from public, anon, authenticated;

-- validates a holder and returns its readable name (raises a friendly message when it is not valid)
create or replace function public._inv_check_holder(sid uuid, p_kind text, p_target uuid, p_label text) returns text
language plpgsql security definer set search_path = public as $$
declare nm text; st text;
begin
  if p_kind = 'location' then
    select name into nm from public.inventory_locations where id = p_target and school_id = sid and active;
    if nm is null then raise exception 'Choose the room / place.'; end if;
  elsif p_kind = 'staff' then
    select name, status into nm, st from public.staff where id = p_target and school_id = sid;
    if nm is null then raise exception 'Choose the staff member.'; end if;
    if st <> 'active' then raise exception '% is no longer working here.', nm; end if;
  elsif p_kind = 'student' then
    select btrim(concat_ws(' ', first_name, last_name)), status into nm, st from public.students where id = p_target and school_id = sid;
    if nm is null then raise exception 'Choose the student.'; end if;
    if st <> 'active' then raise exception '% is no longer on roll.', nm; end if;
  elsif p_kind = 'department' then
    nm := nullif(btrim(coalesce(p_label, '')), '');
    if nm is null then raise exception 'Write the department (for example Science lab, Accounts).'; end if;
  else
    raise exception 'Choose who or where it goes.';
  end if;
  return nm;
end $$;
revoke execute on function public._inv_check_holder(uuid, text, uuid, text) from public, anon, authenticated;

-- ───────────── assign ─────────────
create or replace function public.inventory_assign(sid uuid, p_item uuid, p_qty int, p_kind text, p_target uuid, p_label text default null, p_due date default null,
                                                   p_tag text default null, p_note text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare it public.inventory_items; nm text; aid uuid; me text;
begin
  if auth.uid() is null or not public.has_perm_school(sid, 'inventory.assign.create') then raise exception 'not allowed'; end if;
  if p_qty is null or p_qty <= 0 then raise exception 'Enter how many.'; end if;
  select * into it from public.inventory_items where id = p_item and school_id = sid for update;
  if it.id is null or not it.active then raise exception 'Item not found or withdrawn.'; end if;
  if it.kind = 'shop' then raise exception '“%” is a shop item — it is sold, not assigned.', it.name; end if;
  nm := public._inv_check_holder(sid, p_kind, p_target, p_label);
  if p_due is not null and p_due < public.today_ist() then raise exception 'The return date is in the past.'; end if;
  if it.on_hand < p_qty then raise exception 'Only % of “%” in the store.', it.on_hand, it.name; end if;
  me := public._inv_me(sid);
  insert into public.inventory_assignments (school_id, item_id, qty, holder_kind, location_id, staff_id, student_id, department, tag, due_back, note, assigned_by_name)
  values (sid, p_item, p_qty, p_kind, case when p_kind = 'location' then p_target end, case when p_kind = 'staff' then p_target end, case when p_kind = 'student' then p_target end,
          case when p_kind = 'department' then nm end, nullif(left(btrim(coalesce(p_tag, '')), 60), ''), p_due, nullif(left(btrim(coalesce(p_note, '')), 200), ''), me) returning id into aid;
  insert into public.inventory_moves (school_id, item_id, kind, qty, unit_cost, ref_type, ref_id, party, by_name) values (sid, p_item, 'assign', -p_qty, it.cost, 'assignment', aid, nm, me);
  perform public._inv_event(sid, aid, 'assigned', p_qty || ' × ' || it.name || ' to ' || nm);
  return jsonb_build_object('id', aid, 'holder', nm, 'holder_kind', p_kind, 'item', it.name, 'qty', p_qty, 'due_back', p_due);
end $$;

-- ───────────── return ─────────────
-- p_condition: good (back to the store) | needs_repair (a repair ticket, out of the store) | damaged | lost (written off).
-- p_charge > 0 for a student's damaged / lost item bills the student's fee account.
create or replace function public.inventory_return(sid uuid, p_assignment uuid, p_qty int default null, p_condition text default 'good', p_note text default null, p_charge numeric default 0) returns jsonb
language plpgsql security definer set search_path = public as $$
declare a public.inventory_assignments; it public.inventory_items; n int; closed uuid; nm text; me text; due uuid; chg numeric := greatest(coalesce(p_charge, 0), 0);
begin
  if auth.uid() is null or not public.has_perm_school(sid, 'inventory.assign.edit') then raise exception 'not allowed'; end if;
  if p_condition not in ('good', 'needs_repair', 'damaged', 'lost') then raise exception 'Choose the condition it came back in.'; end if;
  select * into a from public.inventory_assignments where id = p_assignment and school_id = sid for update;
  if a.id is null then raise exception 'Record not found.'; end if;
  if a.status <> 'active' then raise exception 'This was already returned.'; end if;
  n := coalesce(p_qty, a.qty);
  if n <= 0 or n > a.qty then raise exception 'You can return between 1 and %.', a.qty; end if;
  select * into it from public.inventory_items where id = a.item_id for update;
  nm := public._inv_holder(sid, a);
  me := public._inv_me(sid);
  if chg > 0 and a.holder_kind <> 'student' then raise exception 'A recovery charge can be added only for a student.'; end if;
  if chg > 0 and p_condition not in ('damaged', 'lost') then raise exception 'A recovery charge is for damaged or lost property.'; end if;

  if n < a.qty then
    update public.inventory_assignments set qty = qty - n where id = a.id;
    insert into public.inventory_assignments (school_id, item_id, qty, holder_kind, location_id, staff_id, student_id, department, tag, assigned_on, due_back, note, status, returned_on,
                                              return_condition, return_note, assigned_by_name, returned_by_name)
    values (a.school_id, a.item_id, n, a.holder_kind, a.location_id, a.staff_id, a.student_id, a.department, a.tag, a.assigned_on, a.due_back, a.note,
            case p_condition when 'good' then 'returned' when 'needs_repair' then 'repair' when 'damaged' then 'damaged' else 'lost' end, public.today_ist(), p_condition,
            nullif(left(btrim(coalesce(p_note, '')), 200), ''), a.assigned_by_name, me) returning id into closed;
  else
    closed := a.id;
    update public.inventory_assignments set status = case p_condition when 'good' then 'returned' when 'needs_repair' then 'repair' when 'damaged' then 'damaged' else 'lost' end,
           returned_on = public.today_ist(), return_condition = p_condition, return_note = nullif(left(btrim(coalesce(p_note, '')), 200), ''), returned_by_name = me where id = a.id;
  end if;

  if p_condition = 'good' then
    insert into public.inventory_moves (school_id, item_id, kind, qty, unit_cost, ref_type, ref_id, party, by_name) values (sid, a.item_id, 'return', n, it.cost, 'assignment', closed, nm, me);
  elsif p_condition = 'needs_repair' then
    insert into public.inventory_repairs (school_id, item_id, qty, assignment_id, location_id, issue, removed, by_name)
    values (sid, a.item_id, n, closed, a.location_id, coalesce(nullif(btrim(coalesce(p_note, '')), ''), 'Came back needing repair'), true, me);
  else
    -- the unit comes back and is written off, so the ledger shows both
    insert into public.inventory_moves (school_id, item_id, kind, qty, unit_cost, ref_type, ref_id, party, note, by_name) values (sid, a.item_id, 'return', n, it.cost, 'assignment', closed, nm, null, me);
    insert into public.inventory_moves (school_id, item_id, kind, qty, unit_cost, ref_type, ref_id, party, note, by_name) values (sid, a.item_id, 'writeoff', -n, it.cost, 'assignment', closed, nm, p_condition, me);
  end if;

  if chg > 0 then
    due := public.charge_student(sid, a.student_id, 'Damage / Loss Recovery', 'Recovery · ' || it.name || ' (' || p_condition || ')', chg, public.today_ist(), 'asset:' || closed);
    update public.inventory_assignments set charge_due_id = due where id = closed;
  end if;
  perform public._inv_event(sid, closed, 'returned', n || ' × ' || it.name || ' from ' || nm || ' — ' || p_condition || case when chg > 0 then ' · charged ₹' || chg else '' end);
  return jsonb_build_object('id', closed, 'holder', nm, 'holder_kind', a.holder_kind, 'item', it.name, 'qty', n, 'condition', p_condition, 'charged', chg, 'due_id', due);
end $$;

-- ───────────── move an installed item to another place / person ─────────────
create or replace function public.inventory_transfer(sid uuid, p_assignment uuid, p_kind text, p_target uuid, p_label text default null, p_note text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare a public.inventory_assignments; before text; nm text;
begin
  if auth.uid() is null or not public.has_perm_school(sid, 'inventory.assign.edit') then raise exception 'not allowed'; end if;
  select * into a from public.inventory_assignments where id = p_assignment and school_id = sid for update;
  if a.id is null or a.status <> 'active' then raise exception 'This is not currently assigned.'; end if;
  before := public._inv_holder(sid, a);
  nm := public._inv_check_holder(sid, p_kind, p_target, p_label);
  update public.inventory_assignments set holder_kind = p_kind, location_id = case when p_kind = 'location' then p_target end, staff_id = case when p_kind = 'staff' then p_target end,
         student_id = case when p_kind = 'student' then p_target end, department = case when p_kind = 'department' then nm end where id = p_assignment;
  perform public._inv_event(sid, p_assignment, 'transferred', 'from ' || before || ' to ' || nm || coalesce(' — ' || nullif(btrim(coalesce(p_note, '')), ''), ''));
  return jsonb_build_object('id', p_assignment, 'from', before, 'to', nm, 'holder_kind', p_kind, 'qty', a.qty, 'item_id', a.item_id);
end $$;

-- ───────────── repairs ─────────────
create or replace function public.inventory_report_fault(sid uuid, p_item uuid, p_qty int, p_issue text, p_location uuid default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare i uuid;
begin
  if auth.uid() is null or not (public.has_perm_school(sid, 'inventory.assign.create') or public.has_perm_school(sid, 'inventory.assign.edit')) then raise exception 'not allowed'; end if;
  if not exists (select 1 from public.inventory_items where id = p_item and school_id = sid) then raise exception 'Item not found.'; end if;
  if coalesce(btrim(p_issue), '') = '' then raise exception 'Describe the fault.'; end if;
  insert into public.inventory_repairs (school_id, item_id, qty, location_id, issue, by_name)
  values (sid, p_item, greatest(coalesce(p_qty, 1), 1), p_location, left(btrim(p_issue), 300), public._inv_me(sid)) returning id into i;
  return i;
end $$;

create or replace function public.inventory_repair_close(sid uuid, p_repair uuid, p_result text, p_cost numeric default null, p_note text default null, p_vendor text default null) returns void
language plpgsql security definer set search_path = public as $$
declare r public.inventory_repairs; it public.inventory_items;
begin
  if auth.uid() is null or not public.has_perm_school(sid, 'inventory.assign.edit') then raise exception 'not allowed'; end if;
  if p_result not in ('fixed', 'written_off') then raise exception 'Choose fixed or written off.'; end if;
  select * into r from public.inventory_repairs where id = p_repair and school_id = sid for update;
  if r.id is null or r.status <> 'open' then raise exception 'This repair is not open.'; end if;
  if coalesce(p_cost, 0) < 0 then raise exception 'The cost cannot be negative.'; end if;
  update public.inventory_repairs set status = p_result, cost = p_cost, vendor = nullif(left(btrim(coalesce(p_vendor, '')), 80), ''), result_note = nullif(left(btrim(coalesce(p_note, '')), 200), ''),
         closed_on = public.today_ist(), closed_by_name = public._inv_me(sid) where id = p_repair;
  if r.removed then
    select * into it from public.inventory_items where id = r.item_id for update;
    if p_result = 'fixed' then
      insert into public.inventory_moves (school_id, item_id, kind, qty, unit_cost, ref_type, ref_id, note, by_name) values (sid, r.item_id, 'return', r.qty, it.cost, 'repair', r.id, 'Repaired', public._inv_me(sid));
    end if;
  end if;
end $$;

-- ───────────── lists ─────────────
create or replace function public.inventory_assignment_list(sid uuid, p_state text default 'active', p_holder text default null, p_q text default null, p_item uuid default null,
                                                           p_location uuid default null, p_staff uuid default null, p_student uuid default null, p_limit int default 25, p_offset int default 0)
returns table (id uuid, item_id uuid, item_name text, category text, qty int, tag text, holder_kind text, holder_id uuid, holder_name text, holder_sub text, assigned_on date, due_back date,
               days_overdue int, status text, returned_on date, return_condition text, note text, return_note text, assigned_by_name text, returned_by_name text, charge numeric, total bigint)
language sql stable security definer set search_path = public as $$
  select a.id, i.id, i.name || coalesce(' (' || i.variant || ')', ''), i.category, a.qty, a.tag, a.holder_kind, coalesce(a.location_id, a.staff_id, a.student_id),
         case a.holder_kind when 'location' then l.name when 'staff' then w.name when 'student' then btrim(concat_ws(' ', s.first_name, s.last_name)) else a.department end,
         case a.holder_kind when 'location' then concat_ws(' · ', initcap(l.kind), c.name || coalesce('-' || sec.name, ''), l.building)
                            when 'staff' then concat_ws(' · ', w.designation, w.emp_code)
                            when 'student' then concat_ws(' · ', s.admission_no, sc.name || coalesce('-' || ss.name, '')) else 'Department' end,
         a.assigned_on, a.due_back, case when a.status = 'active' and a.due_back is not null and a.due_back < public.today_ist() then public.today_ist() - a.due_back else 0 end,
         a.status, a.returned_on, a.return_condition, a.note, a.return_note, a.assigned_by_name, a.returned_by_name,
         (select d.amount from public.fee_dues d where d.id = a.charge_due_id), count(*) over ()
    from public.inventory_assignments a
    join public.inventory_items i on i.id = a.item_id
    left join public.inventory_locations l on l.id = a.location_id
    left join public.classes c on c.id = l.class_id
    left join public.sections sec on sec.id = l.section_id
    left join public.staff w on w.id = a.staff_id
    left join public.students s on s.id = a.student_id
    left join public.classes sc on sc.id = s.class_id
    left join public.sections ss on ss.id = s.section_id
   where a.school_id = sid and (public.has_perm_school(sid, 'inventory.assign.view') or public.has_perm_school(sid, 'inventory.items.view'))
     and (p_state = 'all' or (p_state = 'active' and a.status = 'active') or (p_state = 'overdue' and a.status = 'active' and a.due_back < public.today_ist())
          or (p_state = 'closed' and a.status <> 'active') or (p_state = 'problem' and a.status in ('damaged', 'lost', 'repair')))
     and (p_holder is null or a.holder_kind = p_holder) and (p_item is null or a.item_id = p_item) and (p_location is null or a.location_id = p_location)
     and (p_staff is null or a.staff_id = p_staff) and (p_student is null or a.student_id = p_student)
     and (nullif(btrim(coalesce(p_q, '')), '') is null or concat_ws(' ', i.name, i.variant, i.sku, a.tag, l.name, w.name, s.first_name, s.last_name, s.admission_no, a.department) ilike public.like_escape(btrim(p_q)))
   order by case when a.status = 'active' then 0 else 1 end, a.due_back nulls last, a.assigned_on desc, a.created_at desc
   limit least(greatest(coalesce(p_limit, 25), 1), 200) offset greatest(coalesce(p_offset, 0), 0);
$$;

-- one row per place with how much property it holds
create or replace function public.inventory_location_summary(sid uuid)
returns table (id uuid, name text, kind text, class_name text, section_name text, building text, in_charge text, active boolean, kinds bigint, units bigint, value numeric)
language sql stable security definer set search_path = public as $$
  select l.id, l.name, l.kind, c.name, sec.name, l.building, w.name, l.active,
         count(distinct a.item_id) filter (where a.status = 'active'), coalesce(sum(a.qty) filter (where a.status = 'active'), 0)::bigint,
         coalesce(sum(a.qty * i.cost) filter (where a.status = 'active'), 0)
    from public.inventory_locations l
    left join public.classes c on c.id = l.class_id left join public.sections sec on sec.id = l.section_id left join public.staff w on w.id = l.in_charge_staff_id
    left join public.inventory_assignments a on a.location_id = l.id
    left join public.inventory_items i on i.id = a.item_id
   where l.school_id = sid and (public.has_perm_school(sid, 'inventory.assign.view') or public.has_perm_school(sid, 'inventory.items.view'))
   group by l.id, l.name, l.kind, c.name, sec.name, l.building, w.name, l.active, c.sort
   order by c.sort nulls last, l.name;
$$;

-- items with what is in the store, out, and under repair (replaces the shop-only list)
drop function if exists public.inventory_item_list(uuid, text, text, text, text, int, int);
create or replace function public.inventory_item_list(sid uuid, p_q text default null, p_category text default null, p_state text default null, p_active text default 'yes',
                                                      p_limit int default 25, p_offset int default 0, p_kind text default null)
returns table (id uuid, sku text, name text, category text, variant text, unit text, cost numeric, price numeric, reorder_level int, track_stock boolean, on_hand int,
               stock_value numeric, active boolean, class_name text, location text, sold_30 bigint, state text, total bigint, kind text, assigned_qty bigint, repair_qty bigint, owned_qty bigint)
language sql stable security definer set search_path = public as $$
  select i.id, i.sku, i.name, i.category, i.variant, i.unit, i.cost, i.price, i.reorder_level, i.track_stock, i.on_hand, round(i.on_hand * i.cost, 2), i.active, c.name, i.location,
         coalesce((select sum(-m.qty) from public.inventory_moves m where m.item_id = i.id and m.kind = 'sale' and m.created_at >= now() - interval '30 days'), 0)::bigint,
         case when not i.track_stock then 'na' when i.on_hand <= 0 then 'out' when i.on_hand <= i.reorder_level then 'low' else 'ok' end, count(*) over (), i.kind,
         coalesce((select sum(a.qty) from public.inventory_assignments a where a.item_id = i.id and a.status = 'active'), 0)::bigint,
         coalesce((select sum(r.qty) from public.inventory_repairs r where r.item_id = i.id and r.status = 'open' and r.removed), 0)::bigint,
         (i.on_hand + coalesce((select sum(a.qty) from public.inventory_assignments a where a.item_id = i.id and a.status = 'active'), 0)
                    + coalesce((select sum(r.qty) from public.inventory_repairs r where r.item_id = i.id and r.status = 'open' and r.removed), 0))::bigint
    from public.inventory_items i left join public.classes c on c.id = i.for_class_id
   where i.school_id = sid and (public.has_perm_school(sid, 'inventory.items.view') or public.has_perm_school(sid, 'inventory.sales.create') or public.has_perm_school(sid, 'inventory.purchase.create')
                                or public.has_perm_school(sid, 'inventory.assign.view') or public.has_perm_school(sid, 'inventory.assign.create'))
     and (p_active is null or p_active = 'all' or (p_active = 'yes' and i.active) or (p_active = 'no' and not i.active))
     and (p_category is null or i.category = p_category) and (p_kind is null or i.kind = p_kind)
     and (p_state is null or (p_state = 'out' and i.track_stock and i.on_hand <= 0) or (p_state = 'low' and i.track_stock and i.on_hand > 0 and i.on_hand <= i.reorder_level)
          or (p_state = 'attention' and i.track_stock and i.on_hand <= i.reorder_level) or (p_state = 'ok' and (not i.track_stock or i.on_hand > i.reorder_level)))
     and (nullif(btrim(coalesce(p_q, '')), '') is null or concat_ws(' ', i.name, i.sku, i.category, i.variant, i.barcode) ilike public.like_escape(btrim(p_q)))
   order by i.category, i.name, i.variant
   limit least(greatest(coalesce(p_limit, 25), 1), 200) offset greatest(coalesce(p_offset, 0), 0);
$$;

create or replace function public.inventory_repair_list(sid uuid, p_state text default 'open', p_limit int default 25, p_offset int default 0)
returns table (id uuid, item_name text, qty int, issue text, location_name text, holder_name text, reported_on date, status text, cost numeric, vendor text, closed_on date, result_note text,
               by_name text, removed boolean, days_open int, total bigint)
language sql stable security definer set search_path = public as $$
  select r.id, i.name || coalesce(' (' || i.variant || ')', ''), r.qty, r.issue, l.name, public._inv_holder(sid, a), r.reported_on, r.status, r.cost, r.vendor, r.closed_on, r.result_note, r.by_name, r.removed,
         case when r.status = 'open' then public.today_ist() - r.reported_on else 0 end, count(*) over ()
    from public.inventory_repairs r join public.inventory_items i on i.id = r.item_id
    left join public.inventory_locations l on l.id = r.location_id left join public.inventory_assignments a on a.id = r.assignment_id
   where r.school_id = sid and (public.has_perm_school(sid, 'inventory.assign.view') or public.has_perm_school(sid, 'inventory.items.view'))
     and (p_state = 'all' or r.status = p_state)
   order by case when r.status = 'open' then 0 else 1 end, r.reported_on desc
   limit least(greatest(coalesce(p_limit, 25), 1), 200) offset greatest(coalesce(p_offset, 0), 0);
$$;

create or replace function public.inventory_overview(sid uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare d date := public.today_ist();
begin
  if not (public.has_perm_school(sid, 'inventory.assign.view') or public.has_perm_school(sid, 'inventory.items.view')) then raise exception 'not allowed'; end if;
  return jsonb_build_object(
    'kinds', (select count(*) from public.inventory_items where school_id = sid and active and kind <> 'shop'),
    'in_store', (select coalesce(sum(on_hand), 0) from public.inventory_items where school_id = sid and active and kind <> 'shop' and track_stock),
    'assigned', (select coalesce(sum(a.qty), 0) from public.inventory_assignments a join public.inventory_items i on i.id = a.item_id where a.school_id = sid and a.status = 'active' and i.kind <> 'shop'),
    'with_people', (select coalesce(sum(qty), 0) from public.inventory_assignments where school_id = sid and status = 'active' and holder_kind in ('staff', 'student')),
    'in_rooms', (select coalesce(sum(qty), 0) from public.inventory_assignments where school_id = sid and status = 'active' and holder_kind = 'location'),
    'overdue', (select count(*) from public.inventory_assignments where school_id = sid and status = 'active' and due_back < d),
    'repairs', (select count(*) from public.inventory_repairs where school_id = sid and status = 'open'),
    'low', (select count(*) from public.inventory_items where school_id = sid and active and kind <> 'shop' and track_stock and on_hand <= reorder_level and reorder_level > 0),
    'value', (select coalesce(sum((i.on_hand + coalesce(x.q, 0)) * i.cost), 0) from public.inventory_items i
              left join (select item_id, sum(qty) q from public.inventory_assignments where status = 'active' group by item_id) x on x.item_id = i.id
              where i.school_id = sid and i.active and i.kind <> 'shop'),
    'by_category', coalesce((select jsonb_agg(jsonb_build_object('name', category, 'units', u) order by u desc) from (
        select i.category, i.on_hand + coalesce(x.q, 0) u from public.inventory_items i
          left join (select item_id, sum(qty) q from public.inventory_assignments where status = 'active' group by item_id) x on x.item_id = i.id
         where i.school_id = sid and i.active and i.kind <> 'shop') q where u > 0 limit 8), '[]'::jsonb),
    'recent', coalesce((select jsonb_agg(jsonb_build_object('at', at, 'by', by_name, 'action', action, 'detail', detail)) from (
        select at, by_name, action, detail from public.inventory_assignment_events where school_id = sid order by at desc limit 8) e), '[]'::jsonb));
end $$;

-- ───────────── clearance: what stands between a student and the Transfer Certificate ─────────────
alter table public.fee_settings add column if not exists tc_clearance text not null default 'all' check (tc_clearance in ('all', 'due_till_today'));

create or replace function public.student_clearance(sid uuid, stu uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare mode text; owed numeric; lst jsonb; books int; assets int; bed boolean;
begin
  if not (public.can_student(sid, 'students.profile.view', stu) or public.can_student(sid, 'documents.issue.view', stu) or public.can_student(sid, 'fees.collection.view', stu)
          or public.has_perm_school(sid, 'documents.issue.create')) then raise exception 'not allowed'; end if;
  select coalesce((select tc_clearance from public.fee_settings where school_id = sid), 'all') into mode;
  select coalesce(sum(greatest(d.amount - d.concession + d.fine - d.paid, 0)), 0),
         coalesce(jsonb_agg(jsonb_build_object('label', d.label, 'balance', greatest(d.amount - d.concession + d.fine - d.paid, 0), 'due_date', d.due_date) order by d.due_date)
                  filter (where d.amount - d.concession + d.fine - d.paid > 0), '[]'::jsonb)
    into owed, lst from public.fee_dues d
   where d.student_id = stu and d.school_id = sid and (mode = 'all' or d.due_date <= public.today_ist());
  select count(*) into books from public.library_issues where student_id = stu and returned_on is null;
  select coalesce(sum(qty), 0) into assets from public.inventory_assignments where student_id = stu and status = 'active';
  select exists (select 1 from public.hostel_allocations where student_id = stu and status = 'active') into bed;
  return jsonb_build_object('owed', owed, 'dues', lst, 'mode', mode, 'books_out', books, 'assets_out', assets, 'hostel_bed', bed, 'fees_clear', owed <= 0);
end $$;

-- the Transfer Certificate rule, applied to every way a TC can be made (template studio and the old certificate screen)
do $$
begin
  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'issue_document_core') then
    alter function public.issue_document(uuid, uuid, uuid, uuid, date, jsonb, boolean, text) rename to issue_document_core;
  end if;
  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'issue_certificate_core') then
    alter function public.issue_certificate(uuid, uuid, text, date, jsonb, boolean, text) rename to issue_certificate_core;
  end if;
end $$;
revoke execute on function public.issue_document_core(uuid, uuid, uuid, uuid, date, jsonb, boolean, text) from public, anon, authenticated;
revoke execute on function public.issue_certificate_core(uuid, uuid, text, date, jsonb, boolean, text) from public, anon, authenticated;

create or replace function public._tc_fee_gate(sid uuid, stu uuid) returns void
language plpgsql security definer set search_path = public as $$
declare mode text; owed numeric;
begin
  select coalesce((select tc_clearance from public.fee_settings where school_id = sid), 'all') into mode;
  select coalesce(sum(greatest(amount - concession + fine - paid, 0)), 0) into owed from public.fee_dues
   where student_id = stu and school_id = sid and (mode = 'all' or due_date <= public.today_ist());
  if owed > 0 then
    raise exception 'The Transfer Certificate cannot be issued: ₹% of fees is still pending for this student. Collect it at the fee counter (or have the principal waive it) first.', owed;
  end if;
end $$;
revoke execute on function public._tc_fee_gate(uuid, uuid) from public, anon, authenticated;

create or replace function public.issue_document(sid uuid, tpl uuid, stu uuid, stf uuid, p_issued_on date, p_extra jsonb default '{}', p_mark_left boolean default false, p_by text default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare t record;
begin
  if stu is not null then
    select on_issue, numbering_prefix, code into t from public.document_templates where id = tpl and school_id = sid;
    if t.on_issue = 'mark_transferred' or upper(coalesce(t.numbering_prefix, '')) = 'TC' or lower(coalesce(t.code, '')) in ('tc', 'transfer_certificate', 'transfer') then
      perform public._tc_fee_gate(sid, stu);
    end if;
  end if;
  return public.issue_document_core(sid, tpl, stu, stf, p_issued_on, p_extra, p_mark_left, p_by);
end $$;

create or replace function public.issue_certificate(sid uuid, stu uuid, p_kind text, p_issued_on date, p_extra jsonb default '{}', p_mark_left boolean default false, p_by text default null)
returns uuid language plpgsql security definer set search_path = public as $$
begin
  if p_kind = 'transfer' then perform public._tc_fee_gate(sid, stu); end if;
  return public.issue_certificate_core(sid, stu, p_kind, p_issued_on, p_extra, p_mark_left, p_by);
end $$;

do $$
declare t text;
begin
  foreach t in array array['inventory_locations', 'inventory_assignments', 'inventory_repairs'] loop
    execute format('drop trigger if exists audit_%1$s on public.%1$I', t);
    execute format('create trigger audit_%1$s after insert or update or delete on public.%1$I for each row execute function public.audit_row()', t);
  end loop;
end $$;

